]
order = ["id","title","status","type","milestone","priority","effort","wave","created","updated","labels","cluster","depends_on","source"]
heads = {"feature":["Problem","Evidence","Direction","Acceptance criteria"],"docs":["Problem","Evidence","Direction","Acceptance criteria"]}
fails = 0
def bad(id_, msg):
    global fails; fails += 1; print(f"FAIL {id_}: {msg}")
for (id_, rel, title, typ, pri, eff, wave, deps, cluster, ev) in rows:
    path = os.path.join(base, rel)
    if not os.path.isfile(path): bad(id_, "missing file"); continue
    text = open(path, encoding="utf-8").read()
    m = re.match(r"^---\n(.*?)\n---\n(.*)$", text, re.S)
    if not m: bad(id_, "no front-matter"); continue
    fm = {}
    keys = []
    for line in m.group(1).splitlines():
        k, v = line.split(": ", 1); keys.append(k); fm[k] = v
    t = fm["title"]
    if t.startswith('"'): t = t[1:-1]
    exp = {"id":id_,"status":"open","type":typ,"milestone":"tracking","priority":pri,"effort":eff,"wave":wave,"created":"2026-10-17","updated":"2026-10-17","depends_on":"["+", ".join(deps)+"]","source":'"sift-prime from docs/PRD.md, 2026-10-17"'}
    for k, v in exp.items():
        if fm.get(k) != v: bad(id_, f"{k}={fm.get(k)!r} expected {v!r}")
    if t != title: bad(id_, f"title {t!r}")
    if cluster: 
        if fm.get("cluster") != cluster: bad(id_, "cluster")
    elif "cluster" in fm: bad(id_, "unexpected cluster")
    if "resolution" in fm: bad(id_, "resolution present")
    labels = re.fullmatch(r"\[(.*)\]", fm.get("labels",""))
    ls = [x.strip() for x in labels.group(1).split(",")] if labels else []
    if not (2 <= len(ls) <= 4) or not all(re.fullmatch(r"[a-z0-9]+(-[a-z0-9]+)*", x) for x in ls): bad(id_, f"labels {ls}")
    if keys != [k for k in order if k in keys]: bad(id_, f"key order {keys}")
    if not os.path.basename(rel).startswith(id_ + "--"): bad(id_, "filename")
    if os.path.basename(os.path.dirname(rel)) != typ: bad(id_, "category folder")
    body = m.group(2)
    if not body.lstrip("\n").startswith("# " + title + "\n"): bad(id_, "H1 mismatch")
    hs = re.findall(r"^## (.+)$", body, re.M)
    if hs != heads[typ]: bad(id_, f"headings {hs}")
    evsec = re.search(r"^## Evidence\n\n(.*?)\n\n## ", body, re.S | re.M).group(1)
    bullets = [l[2:] for l in evsec.splitlines()]
    if bullets != ev: bad(id_, f"evidence {bullets}")
    ac = re.search(r"^## Acceptance criteria\n\n(.*)$", body, re.S | re.M).group(1).strip().splitlines()
    if not ac or not all(l.startswith("- [ ] ") for l in ac): bad(id_, "acceptance format")
    prob = re.search(r"^## Problem\n\n(.*?)\n\n## ", body, re.S | re.M).group(1)
    n = len(re.findall(r"[.!?](?:\s|$)(?![a-z])", prob.replace("e.g.", "eg")))
    if not (2 <= n <= 6): bad(id_, f"problem sentences ~{n}")
    # every cited site appears in Problem/Direction/Acceptance
    rest = body.replace(evsec, "")
    for c in ev:
        key = c.replace("absent: ", "")
        if key not in rest: bad(id_, f"citation not covered in body: {c}")
    print(f"ok-checked {id_} labels={ls} problem_sentences~{n}")
print("FAILS", fails)
EOF
python3 -I "$tmp/check.py"; rm -rf "$tmp"

