feat = ["# ","## Problem","## Evidence","## Direction","## Acceptance criteria"]
ms = open(root+"/.ai/sift/MILESTONES.md").read()
bad = 0
for (tid,rel,title,typ,pri,eff,mil,wave,deps,cl,ev) in rows:
    p = O+rel; errs=[]
    if not os.path.isfile(p): print("MISSING",p); bad+=1; continue
    t = open(p,encoding="utf-8").read()
    m = re.match(r"---\n(.*?)\n---\n", t, re.S)
    fm_text = m.group(1); body = t[m.end():]
    fm = yaml.safe_load(fm_text) if yaml else None
    keys = [l.split(":")[0] for l in fm_text.splitlines()]
    exp = {"id":tid,"title":title,"status":"open","type":typ,"milestone":mil,"priority":pri,"effort":eff,"wave":wave,"depends_on":deps,"source":"sift-prime from docs/PRD.md, 2026-10-17"}
    for k,v in exp.items():
        if fm.get(k)!=v: errs.append(f"{k}={fm.get(k)!r} want {v!r}")
    for k in ("created","updated"):
        if str(fm.get(k))!="2026-10-17": errs.append(f"{k}={fm.get(k)}")
    if cl is None and "cluster" in fm: errs.append("cluster present")
    if cl is not None and fm.get("cluster")!=cl: errs.append(f"cluster={fm.get('cluster')}")
    if "resolution" in fm: errs.append("resolution present")
    labs = fm.get("labels") or []
    if not (2<=len(labs)<=4 and all(re.fullmatch(r"[a-z0-9]+(-[a-z0-9]+)*",l) for l in labs)): errs.append(f"labels {labs}")
    if f"## Milestone" in ms: pass
    if f"## {mil}\n" not in ms: errs.append("milestone not in MILESTONES.md")
    if f"/open/{mil}/{typ}/" not in p: errs.append("folder mismatch")
    if not os.path.basename(p).startswith(tid+"--"): errs.append("filename id")
    order = ["id","title","status","type","milestone","priority","effort","wave","created","updated","labels"]+(["cluster"] if cl else [])+["depends_on","source"]
    if keys!=order: errs.append(f"key order {keys}")
    heads = [l for l in body.splitlines() if l.startswith("#")]
    if heads[0]!="# "+title: errs.append("h1 "+heads[0])
    if heads[1:]!=feat[1:]: errs.append(f"headings {heads}")
    evsec = body.split("## Evidence\n")[1].split("## Direction")[0]
    bullets = [l[2:] for l in evsec.splitlines() if l.startswith("- ")]
    if len(bullets)!=len(ev) or not all(b.startswith(c+" ") or b==c for b,c in zip(bullets,ev)): errs.append(f"evidence {bullets}")
    acc = body.split("## Acceptance criteria\n")[1]
    if not [l for l in acc.splitlines() if l.startswith("- [ ] ")]: errs.append("no criteria")
    prob = body.split("## Problem\n")[1].split("## Evidence")[0].strip()
    ns = len(re.findall(r"[.!?](\s|$)", prob))
    if not 2<=ns<=6: errs.append(f"problem sentences {ns}")
    for ch,name in (("—","em dash"),("–","en dash"),("“","curly"),("”","curly"),("’","curly")):
        if ch in t: errs.append(name)
    print(("OK  " if not errs else "ERR ")+tid, "; ".join(errs)); bad+=bool(errs)
print("yaml parser:", "yes" if yaml else "no", "| failures:", bad)
