    @AtLargestW
    @Test
    fun theGridFitsAndScrollsSidewaysAtTheLargestFontScale() {
        assertEquals(SystemFontScale.LARGEST, context.resources.configuration.fontScale)
        val report = openWeekly()
        assertTextsFitHeight()
        val total = compose.onNode(androidx.compose.ui.test.hasContentDescription(context.getString(R.string.reports_weekly_total_description, spokenDuration(context.resources, report.total))))
        total.performScrollTo()
        compose.waitForIdle()
        val node = total.fetchSemanticsNode()
        val width = context.resources.displayMetrics.widthPixels
        assertTrue("the week total is on screen after a sideways scroll: ${node.positionOnScreen.x}", node.positionOnScreen.x >= 0 && node.positionOnScreen.x + node.size.width <= width)
        val scrollers = compose.onAllNodes(SemanticsMatcher.keyIsDefined(SemanticsProperties.HorizontalScrollAxisRange)).fetchSemanticsNodes()
        assertTrue("rows scroll sideways", scrollers.isNotEmpty())
