        assertTrue("the grid is wider than the screen", range.maxValue() > 0f)
        assertTrue("all rows scrolled together", scrollers.all { it.config[SemanticsProperties.HorizontalScrollAxisRange].value() == range.value() })
        assertTextsFitHeight()
        for (n in compose.onAllNodes(hasClickAction()).fetchSemanticsNodes()) {
            val t = n.config.getOrNull(SemanticsProperties.Text)?.joinToString().orEmpty()
