            assertTrue("unlabelled ${n.config}", t.isNotBlank() || d.isNotBlank())
        }
    }

    private fun assertNoNumbers(report: WeeklyReport) {
        val s = settings()
        for (seconds in report.dayTotals.filter { it > 0 } + report.total + report.rows.map { it.total }) {
            assertFalse("${s.formatDuration(seconds)} offline", hasNode(hasText(s.formatDuration(seconds), substring = true)))
        }
        assertFalse(hasNode(hasText(string(R.string.reports_weekly_title))))
    }

    /** No text is cut off in height; the grid may run off the side, where it scrolls. */
    private fun assertTextsFitHeight() {
        compose.waitForIdle()
        for (node in compose.onAllNodes(SemanticsMatcher.keyIsDefined(SemanticsProperties.Text), useUnmergedTree = true).fetchSemanticsNodes()) {
            val text = node.config.getOrNull(SemanticsProperties.Text)?.joinToString() ?: continue
            layout(node)?.let { assertFalse("cut off: $text", it.didOverflowHeight) }
        }
    }

    private fun openWeekly(): WeeklyReport {
        scenario = ActivityScenario.launch(MainActivity::class.java)
        compose.waitUntil("app", LOAD_MS) { hasNode(hasText(string(R.string.reports))) }
        compose.onNode(hasText(string(R.string.reports)) and hasClickAction()).performClick()
        compose.waitUntil("summary", LOAD_MS) { state() is ReportsState.Loaded }
        compose.onNode(hasText(string(R.string.reports_tab_weekly)) and hasClickAction()).performClick()
        compose.waitUntil("weekly", LOAD_MS) { (state() as? ReportsState.Loaded)?.report is WeeklyReport }
        compose.waitForIdle()
        return (state() as ReportsState.Loaded).report as WeeklyReport
    }

