import zlib, struct, sys
def read(p):
    d=open(p,'rb').read(); i=8; w=h=0; idat=b''; ct=0
    while i<len(d):
        n=struct.unpack('>I',d[i:i+4])[0]; t=d[i+4:i+8]; c=d[i+8:i+8+n]
        if t==b'IHDR': w,h,bd,ct=struct.unpack('>IIBB',c[:10])
        if t==b'IDAT': idat+=c
        i+=12+n
    bpp={2:3,6:4}[ct]; raw=zlib.decompress(idat); stride=w*bpp; rows=[]; prev=bytearray(stride); o=0
    for y in range(h):
        f=raw[o]; line=bytearray(raw[o+1:o+1+stride]); o+=1+stride
        for x in range(stride):
            a=line[x-bpp] if x>=bpp else 0; b=prev[x]; c=prev[x-bpp] if x>=bpp else 0
            if f==1: line[x]=(line[x]+a)&255
            elif f==2: line[x]=(line[x]+b)&255
            elif f==3: line[x]=(line[x]+(a+b)//2)&255
            elif f==4:
                pa=abs(b-c); pb=abs(a-c); pc=abs(a+b-2*c)
                line[x]=(line[x]+(a if pa<=pb and pa<=pc else b if pb<=pc else c))&255
        rows.append(line); prev=line
    return w,h,bpp,rows
for p in sys.argv[1:]:
    w,h,bpp,rows=read(p); ys=[]
    for y,l in enumerate(rows):
        for x in range(w):
            if l[x*bpp]==255 and l[x*bpp+1]==0 and l[x*bpp+2]==255: ys.append(y); break
    print(p, 'magenta rows', (min(ys),max(ys)) if ys else None, 'count', len(ys))
