/** Scratch check for TKA-0035, not committed. */
class ScratchWeeklyTest {
    private val server = MockWebServer()
    private val weeklies = CopyOnWriteArrayList<Pair<String, JsonObject>>()
    private val io = Queued()
    private val settings = MutableStateFlow<AccountSettings?>(AccountSettings("Pacific/Kiritimati", DayOfWeek.WEDNESDAY, null))
