      {"project_id":3,"project_name":"alpha","project_color":"#06aaf5","seconds":[0,900,0,0,0,0,0]},
      {"project_id":5,"project_name":"Big","project_hex_color":"#990099","seconds":[3600,0,0,0,0,0,0]},
      {"project_id":4,"project_name":"Beta","project_color":"#06aaf5","seconds":[0,0,0,0,0,0,900]}
    ]"""

    @Before
    fun setUp() {
        server.dispatcher = object : Dispatcher() {
            override fun dispatch(request: RecordedRequest): MockResponse = when (request.url.encodedPath) {
                "/api/v9/me" -> json("""{"id":1,"default_workspace_id":7}""")
                "/api/v9/workspaces/7" -> json("""{"id":7,"rounding":1,"rounding_minutes":15}""")
                "/reports/api/v3/workspace/7/search/time_entries" -> json("[]")
                "/reports/api/v3/workspace/7/weekly/time_entries" -> {
                    weeklies += request.url.encodedPath to Json.parseToJsonElement(request.body!!.utf8()).jsonObject
                    json(weeklyBody)
                }
                else -> MockResponse.Builder().code(404).build()
            }
        }
        server.start()
        val url = ServerUrl.parse(server.url("/").toString())!!
        ConfiguredServer.readStoredFrom { url }
        ConfiguredTrust.readFrom(InMemoryServerTrust(url))
        // Tuesday 20 October UTC, Wednesday 21 October at UTC+14.
[credential-related line omitted]
            Clock.fixed(Instant.parse("2026-10-20T11:00:00Z"), ZoneOffset.UTC))
    }

    @After
    fun tearDown() {
        ConfiguredServer.readStoredFrom { null }
        ConfiguredTrust.readFrom(InMemoryServerTrust())
        server.close()
    }

    @Test
    fun weeklyAsksForTheAccountsWeekAndSortsAsTheWebApp() {
        model.open(); io.runAll()
        model.select(RangePreset.THIS_MONTH); io.runAll()
        model.selectTab(ReportTab.WEEKLY)
        val loading = model.state.value as ReportsState.Loading
        assertEquals(RangeSelection(ReportRange(LocalDate.parse("2026-10-21"), LocalDate.parse("2026-10-27")), null), loading.selection)
        io.runAll()
        val loaded = model.state.value as ReportsState.Loaded
        val report = loaded.report as WeeklyReport
        val body = weeklies.last().second
        assertEquals("2026-10-21", body.s("start_date")); assertEquals("2026-10-27", body.s("end_date"))
        assertEquals("1", body.s("rounding")); assertEquals("15", body.s("rounding_minutes"))
        assertEquals(listOf(5L, 4L, 3L, null), report.rows.map { it.id })
        assertEquals(listOf(900L, 0, 0, 0, 0, 0, 900), report.rows[1].seconds)
        assertEquals("#990099", report.rows[0].color)
        assertEquals(listOf(4500L, 900, 0, 0, 0, 0, 1800), report.dayTotals)
        assertEquals(7200L, report.total)
        assertEquals(LocalDate.parse("2026-10-21"), report.weekStart)
        model.shift(-1); io.runAll()
        assertEquals("2026-10-14", weeklies.last().second.s("start_date"))
        assertEquals(ReportRange(LocalDate.parse("2026-10-14"), LocalDate.parse("2026-10-20")), (model.state.value as ReportsState.Loaded).selection.range)
        model.select(RangePreset.TODAY); io.runAll()
        assertEquals(ReportRange(LocalDate.parse("2026-10-21"), LocalDate.parse("2026-10-27")), (model.state.value as ReportsState.Loaded).selection.range)
        model.selectCustom(ReportRange(LocalDate.parse("2026-09-03"), LocalDate.parse("2026-09-20"))); io.runAll()
        assertEquals(ReportRange(LocalDate.parse("2026-09-02"), LocalDate.parse("2026-09-08")), (model.state.value as ReportsState.Loaded).selection.range)
        model.selectTab(ReportTab.SUMMARY); io.runAll()
        assertTrue((model.state.value as ReportsState.Loaded).report is SummaryReport)
        assertEquals(ReportRange(LocalDate.parse("2026-09-02"), LocalDate.parse("2026-09-08")), (model.state.value as ReportsState.Loaded).selection.range)
    }

    @Test
    fun aRowWithoutSevenDaysIsInvalidAndTiesSortByTitle() {
        weeklyBody = """[{"project_id":1,"project_name":"x","seconds":[1,2]}]"""
        model.selectTab(ReportTab.WEEKLY)
        model.open(); io.runAll()
        assertEquals(ReportFailure.Unexpected(null), (model.state.value as ReportsState.Failed).failure)
        val rows = listOf(
            WeeklyRow(2, "beta", null, List(7) { 0L }), WeeklyRow(1, "Alpha", null, List(7) { 0L }), WeeklyRow(3, "alpha", null, List(7) { 0L }),
        )
        assertEquals(listOf("alpha", "Alpha", "beta"), WeeklyReport.of(LocalDate.parse("2026-10-21"), rows).rows.map { it.title })
    }

    @Test
    fun weekRule() {
        val wed = DayOfWeek.WEDNESDAY
        val today = LocalDate.parse("2026-10-21")
        assertEquals(ReportRange(LocalDate.parse("2026-10-21"), LocalDate.parse("2026-10-27")), ReportRange(LocalDate.parse("2026-10-01"), LocalDate.parse("2026-10-31")).week(today, wed))
        assertEquals(ReportRange(LocalDate.parse("2026-09-30"), LocalDate.parse("2026-10-06")), ReportRange(LocalDate.parse("2026-10-01"), LocalDate.parse("2026-10-10")).week(today, wed))
    }

    private fun JsonObject.s(k: String) = getValue(k).jsonPrimitive.content
    private fun json(body: String) = MockResponse.Builder().code(200).body(body).addHeader("Content-Type", "application/json").build()

    private class Queued : CoroutineDispatcher() {
        private val queue = ArrayDeque<Runnable>()
        override fun dispatch(context: CoroutineContext, block: Runnable) { queue.addLast(block) }
        fun runAll() { while (queue.isNotEmpty()) queue.removeFirst().run() }
    }
