// Checks: Intl.NumberFormat(1 fraction digit) == round(shortest String(x), half away from zero).
const fmt = new Intl.NumberFormat('en-US', { maximumFractionDigits: 1, minimumFractionDigits: 1, useGrouping: false });

// Decimal string -> {neg, digits BigInt, scale}
function parseDec(s) {
  let neg = s.startsWith('-'); if (neg) s = s.slice(1);
  let exp = 0; const e = s.indexOf('e'); if (e >= 0) { exp = Number(s.slice(e + 1)); s = s.slice(0, e); }
  let [i, f = ''] = s.split('.');
  return { neg, digits: BigInt(i + f), scale: f.length - exp };
}
function roundHalfExpand(s, places) {
  const { neg, digits, scale } = parseDec(s);
  let v;
  if (scale <= places) v = digits * 10n ** BigInt(places - scale);
  else {
    const div = 10n ** BigInt(scale - places);
    const q = digits / div, r = digits % div;
    v = 2n * r >= div ? q + 1n : q;
  }
  const str = v.toString().padStart(places + 1, '0');
  const out = str.slice(0, -places) + '.' + str.slice(-places);
  return (neg ? '-' : '') + out;
}
let seed = 12345;
function rnd() { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }
let n = 0, bad = 0, diffFixed = 0;
function check(x) {
  n++;
  const a = fmt.format(x), b = roundHalfExpand(String(x), 1);
  if (a !== b) { if (bad++ < 10) console.log('MISMATCH', x, a, b); }
  if (x >= 0 && x.toFixed(1) !== a) diffFixed++;
}
for (let i = 0; i < 2000000; i++) {
  const whole = Math.floor(Math.exp(rnd() * Math.log(1e9))) + 1;
  const part = Math.floor(rnd() * (whole + 1));
  check(part / whole * 100);
}
// tie-heavy: (2k+1)/20 style values from integer pairs
for (let w = 20; w <= 200000; w += 20) for (let k = 0; k < 20; k++) { const p = Math.floor(rnd() * w); check(p / w * 100); }
for (let k = 1; k < 20000; k += 2) { check(k / 20); check(k / 2000 * 100); check(k * 15300 / 600000 * 100 / k); }
for (let i = 0; i < 200000; i++) { const x = rnd() * 1e6; check(x); check(-x); }
console.log({ n, bad, diffFixed });
EOF
