                if (new BigDecimal(Double.toString(x)).compareTo(js) != 0) toStringDiffers++;
            }
        }
        System.out.println("checked=" + n + " mismatches=" + bad + " jdkToStringDiffers=" + toStringDiffers);
        System.exit(bad == 0 ? 0 : 1);
    }
}
