import java.io.*;
import java.math.*;
public class NoAcross {
    static BigDecimal shortest(double x) {
        if (x == 0.0) return BigDecimal.ZERO;
        BigDecimal exact = new BigDecimal(x);
        for (int d = 1; d <= 17; d++) { BigDecimal c = exact.round(new MathContext(d, RoundingMode.HALF_EVEN)); if (Double.parseDouble(c.toString()) == x) return c; }
        return exact;
    }
    public static void main(String[] a) throws Exception {
        long bad = 0; int shown = 0, ts = 0;
        try (BufferedReader r = new BufferedReader(new FileReader(a[0]))) {
            for (String line; (line = r.readLine()) != null; ) {
                String[] p = line.split("\t"); double x = Double.longBitsToDouble(Long.parseUnsignedLong(p[0], 16));
                BigDecimal js = new BigDecimal(p[1]);
                if (shortest(x).compareTo(js) != 0) { bad++; if (shown++ < 3) System.out.println("noAcross differs " + p[1] + " got " + shortest(x)); }
                if (new BigDecimal(Double.toString(x)).compareTo(js) != 0 && ts++ < 4) System.out.println("jdk toString " + Double.toString(x) + " js " + p[1]);
            }
        }
        System.out.println("withoutAcrossMismatches=" + bad);
    }
}
