const out: string[] = [];
const formats = ['improved', 'classic', 'decimal'] as const;
const add = (b: bigint) => { const n = Number(b); for (const f of formats) out.push(`${b}\t${f}\t${formatDuration(n, f)}`); };
for (let s = -100n; s <= 400000n; s++) add(s);
for (let k = 0n; k < 300000n; k++) add(18n + 36n * k + 400000n);
let seed = 0x9e3779b97f4a7c15n;
const next = () => { seed ^= seed << 13n; seed &= (1n << 64n) - 1n; seed ^= seed >> 7n; seed ^= seed << 17n; seed &= (1n << 64n) - 1n; return seed; };
const MIN = -(1n << 63n), MAX = (1n << 63n) - 1n;
for (let i = 0; i < 20000; i++) add(BigInt.asIntN(64, next()));
for (let i = 0; i < 20000; i++) add(next() % (1n << 53n));
for (let i = 0; i < 20000; i++) add((1n << 53n) + next() % ((1n << 63n) - (1n << 53n)));
for (let p = 0n; p < 63n; p++) for (const d of [-2n, -1n, 0n, 1n, 2n]) { const v = (1n << p) + d; if (v >= MIN && v <= MAX) add(v); }
add(MIN); add(MAX);
writeFileSync(process.argv[2], out.join('\n') + '\n');
console.log(out.length);
