{"command": "mkdir -p /tmp/sift-w7-r1a/scripts && cat > /tmp/sift-w7-r1a/scripts/contrast.py <<'EOF'
import sys
def lum(h):
    h=h.lstrip('#'); c=[int(h[i:i+2],16)/255 for i in (0,2,4)]
    c=[x/12.92 if x<=0.04045 else ((x+0.055)/1.055)**2.4 for x in c]
    return 0.2126*c[0]+0.7152*c[1]+0.0722*c[2]
def ratio(a,b):
    la,lb=sorted([lum(a),lum(b)],reverse=True); return (la+0.05)/(lb+0.05)
pairs=[("light billable on band","#0091a8","#f6ebd8"),("light other on band","#e0601d","#f6ebd8"),
("dark billable on band","#0f9bb3","#19203f"),("dark other on band","#e46a2a","#19203f"),
("light billable on surface2","#0091a8","#ecdcbf"),("light other on surface2","#e0601d","#ecdcbf"),
("light band on surface","#f6ebd8","#fffaf1"),("dark band on surface","#19203f","#141a36")]
for n,a,b in pairs: print(f"{n}: {ratio(a,b):.2f}")
# mix check: surface-2 at 50% over surface in srgb
def mix(a,b,t):
    a=a.lstrip('#'); b=b.lstrip('#')
    return '#'+''.join(f"{round(int(a[i:i+2],16)*t+int(b[i:i+2],16)*(1-t)):02x}" for i in (0,2,4))
print("light mix", mix("#ecdcbf","#fffaf1",0.5), "dark mix", mix("#1d2547","#141a36",0.5))
EOF
