for f in sys.argv[1:]:
    r=ET.parse(f).getroot()
    for p in r.iter():
        if p.tag.endswith('remotePackage'):
            path=p.get('path')
            if 'x86_64' not in path: continue
            parts=path.split(';')
            api=parts[1]
            try:
                n=int(api.split('-')[1].split('.')[0])
            except: n=0
            if n<34 and 'Baklava' not in api and 'CANARY' not in api: continue
            ch=p.find('channelRef').get('ref')
            rev='.'.join(x.text for x in p.find('revision'))
            for a in p.iter('archive'):
                sz=a.find('complete/size').text; url=a.find('complete/url').text; sha=a.find('complete/checksum')
                print(path, rev, ch, url, sha.get('type'), sha.text, round(int(sz)/1e6),'MB')
EOF", "description": "List x86_64 system images API 34+"}

