import sys, xml.etree.ElementTree as ET
want={('cmdline-tools;latest','channel-0'),('platform-tools','channel-0'),('emulator','channel-0'),('system-images;android-36;default;x86_64','channel-0')}
for f in sys.argv[1:]:
