    evsec = body.split("## Evidence\n",1)[1].split("\n## ",1)[0]
    bullets = [l[2:] for l in evsec.splitlines() if l.startswith("- ")]
    if len(bullets)!=len(ev): errs.append(f"evidence count {len(bullets)}!={len(ev)}")
    for b,c in zip(bullets,ev):
        if not (b==c or b.startswith(c+" ") or b.startswith(c+".")): errs.append(f"evidence mismatch: {b[:70]} vs {c}")
    ac = body.split("## Acceptance criteria\n",1)[1]
    if not all(l.startswith("- [ ] ") for l in ac.strip().splitlines()): errs.append("acceptance format")
    for ch in ["—","–","“","”","‘","’"]:
        if ch in s: errs.append(f"char {ch!r}")
    print(tid, "OK" if not errs else errs, "| title:", t)
    bad += bool(errs)
sys.exit(bad)
