// formatTime and zonedParts copied from ../tokkl at ba6c03d (settings.ts, common/time.ts).
const formatters = new Map<string, Intl.DateTimeFormat>();
function formatterFor(timeZone: string): Intl.DateTimeFormat {
  let f = formatters.get(timeZone);
  if (!f) {
    f = new Intl.DateTimeFormat('en-US', { timeZone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', weekday: 'short' });
    formatters.set(timeZone, f);
  }
  return f;
}
function zonedParts(date: Date, timeZone: string) {
  const parts: Record<string, string> = {};
  for (const part of formatterFor(timeZone).formatToParts(date)) parts[part.type] = part.value;
  return { hour: Number(parts.hour), minute: Number(parts.minute) };
}
function formatTime(iso: string | Date, settings: { timeZone: string; twelveHour: boolean }): string {
  const p = zonedParts(typeof iso === 'string' ? new Date(iso) : iso, settings.timeZone);
  const minute = String(p.minute).padStart(2, '0');
  if (!settings.twelveHour) return `${String(p.hour).padStart(2, '0')}:${minute}`;
  const hour = p.hour % 12 === 0 ? 12 : p.hour % 12;
  return `${hour}:${minute} ${p.hour < 12 ? 'AM' : 'PM'}`;
}
const cases: [string, string][] = [
  ['2026-10-15T00:00:00Z', 'UTC'], ['2026-10-15T00:05:59Z', 'UTC'], ['2026-10-15T09:05:00Z', 'UTC'],
  ['2026-10-15T11:59:59Z', 'UTC'], ['2026-10-15T12:00:00Z', 'UTC'], ['2026-10-15T12:30:00Z', 'UTC'],
  ['2026-10-15T13:07:00Z', 'UTC'], ['2026-10-15T23:59:59.999Z', 'UTC'],
  ['2026-10-15T12:00:00Z', 'Europe/Madrid'], ['2026-10-15T22:30:00Z', 'Europe/Madrid'],
  ['2026-10-15T03:45:00Z', 'America/New_York'], ['2026-10-15T09:00:00Z', 'Asia/Kolkata'],
];
for (const [iso, tz] of cases) {
  console.log(iso, tz, JSON.stringify(formatTime(iso, { timeZone: tz, twelveHour: false })), JSON.stringify(formatTime(iso, { timeZone: tz, twelveHour: true })));
}
for (const v of [undefined, null, 'H:mm', 'h:mm A', 'h:mm a', 'HH:mm', 'A', '', 5, false, true]) {
  // eslint-disable-next-line
  console.log(JSON.stringify(v), /a/i.test((v as any) ?? 'H:mm'));
