            composeRule.onNode(hasText(string(R.string.timer_view_calendar)) and isSelectable()).performSemanticsAction(SemanticsActions.OnClick)
            awaitDescription("Today entry, from 09:00 to 10:30, 1 hour, 30 minutes")
            // The late call crosses midnight into today: today's column shows its tail.
            awaitDescription("Late call, from 23:30 to 01:00")
            runCatching { ReferenceImages.assertMatches("scratch-calendar-portrait", composeRule.onRoot().captureToImage()) }

            DeviceShell.run("cmd connectivity airplane-mode enable")
            waitForNetwork(false)
            repeat(OLD_DAYS.toInt()) { click(R.string.calendar_previous_day) }
            composeRule.awaitText(string(R.string.calendar_offline_title), 30_000)
            runCatching { ReferenceImages.assertMatches("scratch-calendar-offline", composeRule.onRoot().captureToImage()) }
            composeRule.onNode(hasText(string(R.string.calendar_today))).performSemanticsAction(SemanticsActions.OnClick)
            awaitDescription("Today entry, from 09:00 to 10:30")

            DeviceShell.run("cmd connectivity airplane-mode disable")
            waitForNetwork(true)
            repeat(OLD_DAYS.toInt()) { click(R.string.calendar_previous_day) }
            awaitDescription("Old entry, from 09:00 to 10:00, 1 hour")
            composeRule.onNode(hasText(string(R.string.calendar_today))).performSemanticsAction(SemanticsActions.OnClick)
            awaitDescription("Today entry, from 09:00 to 10:30")

            scenario.onActivity { it.requestedOrientation = ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE }
            composeRule.awaitText(string(R.string.calendar_this_week), 30_000)
            awaitDescription("Today entry, from 09:00 to 10:30")
            awaitDescription("Late call, from 23:30 to 01:00")
            val heads = composeRule.onAllNodes(hasContentDescription(" in total", substring = true)).fetchSemanticsNodes()
                .sortedBy { it.boundsInRoot.left }
                .map { it.config[SemanticsProperties.ContentDescription].joinToString() }
            android.util.Log.i("ScratchCalendar", "heads=$heads")
            assertEquals(7, heads.size)
            val weekStart = today.minusDays((today.dayOfWeek.value % 7).toLong())
            val first = if (weekStart == today) "Today" else "Sun, "
            assertTrue(heads.toString(), heads.first().startsWith(first))
            runCatching { ReferenceImages.assertMatches("scratch-calendar-landscape", composeRule.onRoot().captureToImage()) }
        }
    }

    private fun click(label: Int) {
        composeRule.onNode(hasContentDescription(string(label))).performSemanticsAction(SemanticsActions.OnClick)
        composeRule.waitForIdle()
    }

    private fun awaitDescription(text: String) {
        composeRule.waitUntil("\"$text\" shows", 30_000) {
            composeRule.onAllNodes(hasContentDescription(text, substring = true)).fetchSemanticsNodes().isNotEmpty()
        }
    }

    private fun waitForNetwork(up: Boolean) {
        val deadline = System.nanoTime() + 30_000_000_000L
        while (serverAnswers() != up) {
            if (System.nanoTime() > deadline) throw AssertionError("network did not switch")
            Thread.sleep(200)
        }
    }

    private fun serverAnswers(): Boolean {
        val result = account.client.get(account.client.server.api("me"), JsonObject.serializer())
        return (result as? ApiResult.Failure)?.error !is ApiError.Network
    }

    private fun string(id: Int) = context.getString(id)

    private fun putWeekStart(api: TogglApiClient, day: Int) {
        api.send("PUT", api.server.api("me"), buildJsonObject { put("beginning_of_week", day) }, JsonObject.serializer()).orFail("PUT /me")
    }

    private fun seed(api: TogglApiClient, description: String, day: LocalDate, hour: Int, minute: Int, seconds: Int) {
        val workspace = api.get(api.server.api("me"), Me.serializer()).orFail("GET /api/v9/me").defaultWorkspaceId
        val start = day.atTime(hour, minute).atZone(ZoneId.of(ZONE)).toInstant()
