import androidx.test.core.app.ActivityScenario
import androidx.test.platform.app.InstrumentationRegistry
import com.github.e0ipso.tokkl.MainActivity
import com.github.e0ipso.tokkl.R
import com.github.e0ipso.tokkl.SessionRule
import com.github.e0ipso.tokkl.SignedInFrame
import com.github.e0ipso.tokkl.TestAccounts
import com.github.e0ipso.tokkl.TokklTestServer
import com.github.e0ipso.tokkl.awaitText
import com.github.e0ipso.tokkl.awaitTimerPage
import com.github.e0ipso.tokkl.navigation.TopLevelPage
import com.github.e0ipso.tokkl.orFail
import com.github.e0ipso.tokkl.session.Session
import com.github.e0ipso.tokkl.ui.screenshot.ReferenceImages
import com.github.e0ipso.tokkl.ui.theme.TokklTheme
import java.time.Instant
import java.time.temporal.ChronoUnit
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put
import org.junit.After
import org.junit.Before
import org.junit.Rule
import org.junit.Test
import org.junit.rules.RuleChain

/** Disposable live checks for TKA-0161 on the real Tokkl container. Not committed. */
class ScratchRunningDotTest {
    private val composeRule = createEmptyComposeRule()

    @get:Rule
    val rules: RuleChain = RuleChain.outerRule(SessionRule()).around(composeRule)

    private val context = InstrumentationRegistry.getInstrumentation().targetContext
    private lateinit var account: TestAccounts.Account

    @Before
    fun signIn() {
        account = TestAccounts.create(timezone = "Europe/Madrid")
[credential-related line omitted]
    }

    @After
    fun cleanUp() {
        try {
            if (::account.isInitialized) TestAccounts.delete(account)
        } finally {
            SessionRule.signOut()
        }
    }

    private val running = SemanticsMatcher.expectValue(SemanticsProperties.StateDescription, "Timer running")
    private val timerItem = hasText("Timer") and hasClickAction()

    @Test
    fun dotFollowsTheRunningEntryOnEveryPage() {
        val api = account.client
        val workspace = api.get(api.server.api("me"), Me.serializer()).orFail("GET /api/v9/me").defaultWorkspaceId
        val created = api.send(
            "POST",
            api.server.api("workspaces", workspace.toString(), "time_entries"),
            buildJsonObject {
                put("workspace_id", workspace)
                put("created_with", "tokkl-android tests")
                put("description", "Running")
                put("start", Instant.now().minus(10, ChronoUnit.MINUTES).truncatedTo(ChronoUnit.SECONDS).toString())
                put("duration", -1)
            },
            Created.serializer(),
        ).orFail("POST a running entry")
        ActivityScenario.launch(MainActivity::class.java).use {
            composeRule.awaitTimerPage(30_000)
            composeRule.waitUntil("dot on Timer", 30_000) { composeRule.onAllNodes(timerItem and running).fetchSemanticsNodes().isNotEmpty() }
            for (page in listOf("Reports", "Projects", "Settings")) {
                composeRule.onNode(hasText(page) and hasClickAction()).performSemanticsAction(SemanticsActions.OnClick)
                composeRule.waitForIdle()
                composeRule.onNode(timerItem and running).assertExists()
            }
            composeRule.onNode(hasText("More") and hasClickAction()).performSemanticsAction(SemanticsActions.OnClick)
            composeRule.awaitText("Clients")
            composeRule.onNode(hasText("Clients") and hasClickAction()).performSemanticsAction(SemanticsActions.OnClick)
            composeRule.waitForIdle()
            composeRule.onNode(timerItem and running).assertExists()
            // Stop it on the server; the next refresh, on the next start, clears the dot.
            api.send(
                "PATCH",
                api.server.api("workspaces", workspace.toString(), "time_entries", created.id.toString(), "stop"),
                null,
                JsonObject.serializer(),
            ).orFail("PATCH stop")
        }
        ActivityScenario.launch(MainActivity::class.java).use {
            composeRule.awaitTimerPage(30_000)
            composeRule.waitUntil("no dot on Timer", 30_000) { composeRule.onAllNodes(timerItem and running).fetchSemanticsNodes().isEmpty() }
            composeRule.onNode(timerItem).assertExists()
        }
    }

    @Test
    fun captureDots() {
        for (dark in listOf(false, true)) {
            for (page in listOf(TopLevelPage.SETTINGS, TopLevelPage.TIMER)) {
                ActivityScenario.launch(ComponentActivity::class.java).use { scenario ->
                    scenario.onActivity { activity ->
                        WindowCompat.enableEdgeToEdge(activity.window)
                        activity.setContent { TokklTheme(darkTheme = dark) { SignedInFrame(current = page, onOpen = {}, timerRunning = true) {} } }
                    }
                    composeRule.waitForIdle()
                    runCatching { ReferenceImages.assertMatches("scratch-dot-${page.name.lowercase()}-${if (dark) "dark" else "light"}", composeRule.onRoot().captureToImage()) }
                }
            }
        }
    }

    @Serializable
    private class Me(@SerialName("default_workspace_id") val defaultWorkspaceId: Long)

    @Serializable
    private class Created(val id: Long)
}
