{"command": "python3 -I - <<'EOF'
def lum(h):
    c=[int(h[i:i+2],16)/255 for i in (0,2,4)]
    c=[x/12.92 if x<=0.04045 else ((x+0.055)/1.055)**2.4 for x in c]
    return 0.2126*c[0]+0.7152*c[1]+0.0722*c[2]
def cr(a,b):
    la,lb=sorted([lum(a),lum(b)],reverse=True); return (la+0.05)/(lb+0.05)
light=dict(bg='F4E7CF',glow='DFB698',swell='B9CBBB',stripe='E9CEB3',text='1C1A2B')
dark=dict(bg='0B1026',glow='4F332E',swell='134354',stripe='2D212A',text='F3F1FF',halo='A9B0D6')
def ext(t,f):
    return ''.join('%02X'%f(int(t[k][i:i+2],16) for k in ('glow','swell','stripe','bg')) for i in (0,2,4))
lw=ext(light,min); dw=ext(dark,max)
print('light worst overlap',lw,'text',round(cr(light['text'],lw),2),'outline 00011E',round(cr('00011E',lw),2))
print('dark worst overlap',dw,'text',round(cr(dark['text'],dw),2),'halo',round(cr(dark['halo'],dw),2))
EOF", "description": "Compute contrast on the worst scene overlap"}

