package com.github.e0ipso.tokkl.zzprobe

import android.graphics.Bitmap
import android.os.SystemClock
import android.util.Base64
import android.util.Log
import androidx.test.platform.app.InstrumentationRegistry
import java.io.ByteArrayOutputStream

// Disposable probe for sitting w6-e3. Never committed.
object Shots {
    val phase: String get() = InstrumentationRegistry.getArguments().getString("probePhase") ?: "x"

    fun take(name: String) {
        val instrumentation = InstrumentationRegistry.getInstrumentation()
        instrumentation.waitForIdleSync()
        SystemClock.sleep(800)
        val bitmap = instrumentation.uiAutomation.takeScreenshot() ?: error("no screenshot")
        val scaled = Bitmap.createScaledBitmap(bitmap, bitmap.width / 2, bitmap.height / 2, true)
        val bytes = ByteArrayOutputStream().also { scaled.compress(Bitmap.CompressFormat.PNG, 100, it) }.toByteArray()
        val text = Base64.encodeToString(bytes, Base64.NO_WRAP)
        val chunks = text.chunked(3000)
        val full = "$phase-$name"
        chunks.forEachIndexed { i, chunk ->
            Log.i("SHOT", "$full ${i + 1}/${chunks.size} $chunk")
            if (i % 8 == 7) SystemClock.sleep(50)
        }
        Log.i("SHOT", "$full done ${bytes.size}")
    }

    fun note(text: String) {
        Log.i("PROBE", "$phase $text")
    }
}
EOF
