{"command": "cat > /tmp/sift-w6-e3/decode.py <<'EOF'
import sys, os, re, base64, glob
src, dst = sys.argv[1], sys.argv[2]
os.makedirs(dst, exist_ok=True)
shots = {}
notes = []
for f in sorted(glob.glob(os.path.join(src, '**', 'logcat-*.txt'), recursive=True)):
    for line in open(f, errors='replace'):
        m = re.search(r' SHOT\s*: (\S+) (\d+)/(\d+) (\S+)$', line.rstrip('\n'))
        if m:
            name, i, n, chunk = m.group(1), int(m.group(2)), int(m.group(3)), m.group(4)
            shots.setdefault(name, {})[i] = (n, chunk)
            continue
        m = re.search(r' PROBE\s*: (.*)$', line.rstrip('\n'))
        if m:
            notes.append(m.group(1))
for name, parts in shots.items():
    n = next(iter(parts.values()))[0]
    if len(parts) != n:
        print(f'{name}: incomplete {len(parts)}/{n}')
        continue
    data = ''.join(parts[i][1] for i in range(1, n + 1))
    out = os.path.join(dst, name + '.png')
    open(out, 'wb').write(base64.b64decode(data))
    print(f'{name}: {out}')
for note in notes:
    print('NOTE', note)
EOF
