# pixel-compare before vs after0116 shots that 0116 should not change (radio and checkbox rows)
import zlib, struct
def load(p):
    d=open(p,'rb').read(); pos=8; idat=b''; w=h=0
    while pos<len(d):
        l=struct.unpack('>I',d[pos:pos+4])[0]; t=d[pos+4:pos+8]; c=d[pos+8:pos+8+l]
        if t==b'IHDR': w,h,bd,ct=struct.unpack('>IIBB',c[:10])
        if t==b'IDAT': idat+=c
        pos+=12+l
    return w,h,zlib.decompress(idat)
for name in ['signin-token','http-warning','http-warning-ticked']:
