logs=/tmp/tka0002-logs.maRzQM; sdir=$(mktemp -d /tmp/tka0002-script.XXXXXX); cat > "$sdir/m1-check.mjs" <<'EOF'
const root = '/home/e0ipso/workspace/apps/tokkl/packages/';
const { parseTimeOfDay } = await import(root + 'web/src/lib/timeOfDay.ts');
const { parseDuration } = await import(root + 'common/duration.ts');
const rows = [
  ['time 9', parseTimeOfDay('9'), 540],
  ['time 930', parseTimeOfDay('930'), 570],
  ['time 9:30', parseTimeOfDay('9:30'), 570],
  ['time 4pm', parseTimeOfDay('4pm'), 960],
  ['across midnight, 11pm to "1"', parseTimeOfDay('1', { twelveHour: true, after: 23 * 60 }), 60],
  ['across midnight, 10am to 9am', parseTimeOfDay('9am', { twelveHour: true, after: 600 }), 540],
  ['duration 1h 30m', parseDuration('1h 30m'), 5400],
  ['duration 90', parseDuration('90'), 5400],
  ['duration 1,5h', parseDuration('1,5h'), 5400],
];
let bad = 0;
for (const [label, got, want] of rows) {
  const ok = got === want; if (!ok) bad++;
  console.log(`${ok ? 'ok  ' : 'FAIL'} ${label} -> ${got} (want ${want})`);
}
process.exit(bad ? 1 : 0);
EOF
