package com.github.e0ipso.tokkl.sifthold

import android.os.ParcelFileDescriptor
import androidx.test.platform.app.InstrumentationRegistry
import org.junit.Test
import java.util.concurrent.TimeUnit
import kotlin.concurrent.thread

/** Scratch only: keeps the script's emulator up until the host writes to a FIFO, at most 30 min. */
class SiftHoldTest {
    @Test
    fun hold() {
        val ui = InstrumentationRegistry.getInstrumentation().uiAutomation
        fun sh(cmd: String): String =
            ParcelFileDescriptor.AutoCloseInputStream(ui.executeShellCommand(cmd)).use { it.readBytes().decodeToString() }
        val fifo = "/data/local/tmp/sift-w7-d3-hold"
        sh("rm -f $fifo $fifo-ready")
        sh("mkfifo $fifo")
        sh("touch $fifo-ready")
        val reader = thread { sh("cat $fifo") }
        reader.join(TimeUnit.MINUTES.toMillis(30))
        sh("rm -f $fifo $fifo-ready")
    }
}
EOF
