package com.github.e0ipso.tokkl.cache

import com.github.e0ipso.tokkl.api.ApiCredentials
import com.github.e0ipso.tokkl.api.ConfiguredServer
import com.github.e0ipso.tokkl.api.ConfiguredTrust
import com.github.e0ipso.tokkl.api.InMemoryServerTrust
import com.github.e0ipso.tokkl.api.ServerUrl
import com.github.e0ipso.tokkl.api.TogglApiClient
import java.time.Instant
import java.util.concurrent.CountDownLatch
import java.util.concurrent.TimeUnit
import java.util.concurrent.atomic.AtomicInteger
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.runBlocking
import mockwebserver3.Dispatcher
import mockwebserver3.MockResponse
import mockwebserver3.MockWebServer
import mockwebserver3.RecordedRequest
import org.junit.After
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Before
import org.junit.Test

/** Disposable check for TKA-0177 AC2; not committed. */
class ScratchOnSentTest {
    private val server = MockWebServer()
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)
    private val onSent = AtomicInteger()
    private val changes = ArrayList<PendingChange>()
    private var sequence = 0L
    private lateinit var sender: ChangeSender
    private var firstSent = CountDownLatch(1)
    private var holdFirst = CountDownLatch(0)

    private val store = object : ChangeStore {
        @Synchronized override fun first(): PendingChange? = changes.firstOrNull()
        override fun sent(change: PendingChange, serverId: Long, answer: CachedTimeEntry?) {
            synchronized(this) { changes.removeAll { it.sequence == change.sequence } }
            firstSent.countDown()
            holdFirst.await(5, TimeUnit.SECONDS)
        }
    }

    @Before
    fun setUp() {
        server.dispatcher = object : Dispatcher() {
            override fun dispatch(request: RecordedRequest) = MockResponse.Builder().code(200)
                .addHeader("Content-Type", "application/json")
                .body("""{"id":101,"workspace_id":7,"description":"x","start":"2026-10-19T08:00:00+00:00","stop":null,"tags":[],"tag_ids":[]}""")
                .build()
        }
        server.start()
        val url = ServerUrl.parse(server.url("/").toString())!!
        ConfiguredServer.readStoredFrom { url }
        ConfiguredTrust.readFrom(InMemoryServerTrust(url))
[credential-related line omitted]
    }

    @After
    fun tearDown() {
        scope.cancel()
        ConfiguredServer.readStoredFrom { null }
        ConfiguredTrust.readFrom(InMemoryServerTrust())
        server.close()
    }

    private fun queue(kind: ChangeKind) = synchronized(store) {
        changes += PendingChange(++sequence, kind, 101, 7, null, null, "x", Instant.parse("2026-10-19T08:00:00Z"), null, false, emptyList(), emptyList())
    }

    @Test
    fun oneDrainOfSeveralChangesRefreshesOnce() {
        queue(ChangeKind.UPDATE); queue(ChangeKind.UPDATE); queue(ChangeKind.STOP)
        runBlocking { sender.send().join() }
        assertTrue(changes.isEmpty())
        assertEquals(3, server.requestCount)
        assertEquals(1, onSent.get())
    }

    @Test
    fun aChangeQueuedAfterThePassReadTheQueueRefreshesOnceAfterBothPasses() {
        // The first pass sends the only change, then a tap queues another and calls send() while
        // the pass still runs, so the drain makes a second pass.
        holdFirst = CountDownLatch(1)
        queue(ChangeKind.UPDATE)
        val job = sender.send()
        assertTrue(firstSent.await(5, TimeUnit.SECONDS))
        queue(ChangeKind.STOP)
        val same = sender.send()
        assertTrue("send() returned the running drain", same === job)
        holdFirst.countDown()
        runBlocking { job.join() }
        assertTrue(changes.isEmpty())
        assertEquals(2, server.requestCount)
        assertEquals(1, onSent.get())
    }
}
