mkdir -p /tmp/w3b1-verify && cat > /tmp/w3b1-verify/check-ci.mjs <<'EOF'
// Usage: node check-ci.mjs <repo-root>. Parses ci.yml, checks triggers and that every uses: pins
// a 40-char SHA that git ls-remote confirms for the tag in the trailing comment.
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import assert from 'node:assert/strict';

const root = process.argv[2];
const require = createRequire(`${root}/package.json`);
const yaml = require('js-yaml');
const file = `${root}/.github/workflows/ci.yml`;
const text = readFileSync(file, 'utf8');
const doc = yaml.load(text);

assert.deepEqual(doc.on.pull_request.branches, ['main']);
assert.deepEqual(doc.on.push.branches, ['main']);
console.log('triggers: pull_request and push on main');
console.log('jobs:', Object.keys(doc.jobs).join(', '));

let failures = 0;
const lines = text.split('\n');
let count = 0;
lines.forEach((line, i) => {
  const m = line.match(/^\s*-?\s*uses:\s*(\S+)(?:\s+#\s*(\S+))?\s*$/);
  if (!line.match(/\buses:/)) return;
  count++;
  if (!m) { console.log(`FAIL line ${i + 1}: unparsable ${line}`); failures++; return; }
  const [, ref, version] = m;
  const [slug, sha] = ref.split('@');
  const repo = slug.split('/').slice(0, 2).join('/');
  if (!/^[0-9a-f]{40}$/.test(sha ?? '')) { console.log(`FAIL line ${i + 1}: ${ref} is not a 40-char SHA`); failures++; return; }
  if (!version) { console.log(`FAIL line ${i + 1}: no version comment`); failures++; return; }
  const out = execFileSync('git', ['ls-remote', '--tags', `https://github.com/${repo}`, `refs/tags/${version}`, `refs/tags/${version}^{}`], { encoding: 'utf8' });
  const rows = out.trim().split('\n').filter(Boolean).map(r => r.split('\t'));
  const peeled = rows.find(r => r[1].endsWith('^{}'));
  const commit = (peeled ?? rows[0])?.[0];
  if (commit === sha) console.log(`ok   line ${i + 1}: ${slug} ${version} -> ${sha}${peeled ? ' (peeled annotated tag)' : ''}`);
  else { console.log(`FAIL line ${i + 1}: ${slug} ${version} resolves to ${commit}, file has ${sha}`); failures++; }
});
console.log(`uses lines: ${count}, failures: ${failures}`);
process.exit(failures ? 1 : 0);
EOF
