// Disposable: adds every catalog library to releaseImplementation for one run,
// so the resolved graph can be checked for GMS/Firebase and licences.
allprojects { p ->
    if (p.path == ':app') {
        p.afterEvaluate {
            def libs = p.extensions.getByType(VersionCatalogsExtension).named('libs')
