command:
cat > /tmp/tka0004-scripts/licences.py <<'EOF'
import re, sys, glob, os, collections
import xml.etree.ElementTree as ET
CACHE = os.path.expanduser('~/.gradle/caches/modules-2/files-2.1')
coords = set()
for log in sys.argv[1:]:
    for line in open(log):
        m = re.search(r'--- ([\w.\-]+):([\w.\-]+):(\S+)(?: -> (\S+))?', line)
        if m:
            g, a, v, r = m.groups()
            v = r or v
            if v.startswith('{'): continue
            coords.add((g, a, v))
        m = re.search(r'--- ([\w.\-]+):([\w.\-]+) -> (\S+)', line)
        if m:
            coords.add(m.groups())
def pom(g, a, v):
    p = glob.glob(f'{CACHE}/{g}/{a}/{v}/*/{a}-{v}.pom')
    return p[0] if p else None
def strip(t): return re.sub(r'\{[^}]*\}', '', t)
def lic(g, a, v, depth=0):
    p = pom(g, a, v)
    if not p: return None
    root = ET.parse(p).getroot()
    out = []
    for el in root.iter():
        if strip(el.tag) == 'license':
            name = next((c.text for c in el if strip(c.tag) == 'name'), None)
            out.append((name or '').strip())
    if out: return out
    par = next((c for c in root if strip(c.tag) == 'parent'), None)
    if par is not None and depth < 5:
        f = {strip(c.tag): c.text for c in par}
        return lic(f['groupId'], f['artifactId'], f['version'], depth + 1)
    return []
by = collections.defaultdict(list)
for g, a, v in sorted(coords):
    l = lic(g, a, v)
    key = 'NO POM IN CACHE' if l is None else (' | '.join(sorted(set(l))) or 'NO LICENCE IN POM')
    by[key].append(f'{g}:{a}:{v}')
print('modules:', len(coords))
for k, mods in sorted(by.items(), key=lambda x: -len(x[1])):
    print(f'{len(mods):4d}  {k}')
    if 'NO ' in k or len(mods) < 4:
        for m in mods: print('        ', m)
EOF
