    val rule = createComposeRule()

    @Test
    fun clockTotalsAndHeadingsFitAtDoubleFontScaleOn320dp() {
        val results = linkedMapOf<String, TextLayoutResult>()
        rule.setContent {
            val density = LocalDensity.current
            CompositionLocalProvider(LocalDensity provides Density(density.density, fontScale = 2f)) {
                TokklTheme {
                    val samples: List<Triple<String, String, TextStyle>> = listOf(
                        Triple("clock", "88:88:88", TokklTheme.clockTextStyle),
                        Triple("total", "888:88:88", TokklTheme.totalTextStyle),
                        Triple("headlineLarge", "Tokkl", MaterialTheme.typography.headlineLarge),
                        Triple("headlineMedium", "Licences", MaterialTheme.typography.headlineMedium),
                        Triple("headlineSmall", "Anybody font", MaterialTheme.typography.headlineSmall),
                        Triple("displayLarge", "88:88", MaterialTheme.typography.displayLarge),
                    )
                    Column(Modifier.width(320.dp).padding(horizontal = 16.dp)) {
                        samples.forEach { (name, text, style) ->
                            Text(text, style = style, maxLines = 1, onTextLayout = { results[name] = it })
                        }
                    }
                }
            }
        }
        rule.waitForIdle()
        val failures = results.filter { (_, r) -> r.hasVisualOverflow }.keys
        results.forEach { (name, r) ->
            Log.i(
                "FontScaleCheck",
                "$name fontScale=2 box=288dp size=${r.size} lines=${r.lineCount} " +
                    "overflowWidth=${r.didOverflowWidth} overflowHeight=${r.didOverflowHeight} " +
                    "fontSizePx=${r.layoutInput.style.fontSize} family=${r.layoutInput.style.fontFamily}",
            )
        }
        assertFalse("overflow in $failures", failures.isNotEmpty())
    }
}
