cat > /tmp/sift-w3a3-scripts.aYedxZ/circle.py <<'EOF'
import sys
def pgm(p):
    d = open(p, 'rb').read()
    parts = d.split(b'\n', 3)  # P5, "w h", maxval, data (ImageMagick writes one header item per line)
    w, h = map(int, parts[1].split()); return w, h, parts[3]
w, h, a = pgm(sys.argv[1]); T = int(sys.argv[2])
pts = []
for y in range(h):
    row = y * w
    for x in range(w):
        if a[row + x] >= T:
            # boundary: some 4-neighbour below threshold or image edge
            if x == 0 or y == 0 or x == w-1 or y == h-1 or a[row+x-1] < T or a[row+x+1] < T or a[row-w+x] < T or a[row+w+x] < T:
                pts.append((x, y))
xs = [p[0] for p in pts]; ys = [p[1] for p in pts]
print('boundary points', len(pts), 'bbox', min(xs), min(ys), max(xs), max(ys))
bx, by = (min(xs)+max(xs))/2, (min(ys)+max(ys))/2
best = None
for dy in range(-80, 81, 4):
    for dx in range(-20, 21, 4):
        cx, cy = bx+dx, by+dy
        r = max(((x-cx)**2 + (y-cy)**2) for x, y in pts) ** 0.5
        if best is None or r < best[0]: best = (r, cx, cy)
r, cx, cy = best
for dy in range(-4, 5):
    for dx in range(-4, 5):
        x0, y0 = cx+dx, cy+dy
        rr = max(((x-x0)**2 + (y-y0)**2) for x, y in pts) ** 0.5
        if rr < best[0]: best = (rr, x0, y0)
print('bbox centre', bx, by, 'enclosing circle centre', best[1], best[2], 'radius', round(best[0], 1))
EOF
