import { snapSpan } from '/home/e0ipso/workspace/apps/tokkl/packages/common/snap.ts';
const MAX = 8_640_000_000_000_000;
const H = 3_600_000;
const iso = (d: Date) => (Number.isNaN(d.getTime()) ? 'INVALID' : d.toISOString());
function run(label: string, start: number, stop: number, minutes: number, tz = 'UTC') {
  try {
    const r = snapSpan(new Date(start), new Date(stop), minutes, tz);
    console.log(`${label} | start=${start} stop=${stop} min=${minutes} tz=${tz} -> [${iso(r.start)}, ${iso(r.stop)}] ms=[${r.start.getTime()}, ${r.stop.getTime()}]`);
  } catch (e) {
    console.log(`${label} | start=${start} stop=${stop} min=${minutes} tz=${tz} -> THROWS ${(e as Error).name}: ${(e as Error).message}`);
  }
}
// upper end
run('exact limit as stop, aligned', MAX - H, MAX, 60);
run('exact limit as stop, 15min', MAX - 900_000, MAX, 15);
run('exact limit as both', MAX, MAX, 15);
run('one past stop (invalid Date)', MAX - H, MAX + 1, 60);
run('one past start', MAX + 1, MAX + 1, 15);
run('start at limit-step, zero length', MAX - 900_000, MAX - 900_000, 15);
run('start at limit-step+1, zero length', MAX - 900_000 + 1, MAX - 900_000 + 1, 15);
run('start at limit-step, tiny', MAX - 900_000, MAX - 900_000 + 1, 15);
run('start limit-step-1 zero', MAX - 900_000 - 1, MAX - 900_000 - 1, 15);
run('crossing: start MAX-2h stop MAX-1h-1ms 60', MAX - 2*H, MAX - H + 1, 60);
run('crossing: start MAX-1h+1 stop MAX-1h+2 60', MAX - H + 1, MAX - H + 2, 60);
run('rounding up crosses: start MAX-30m stop MAX-30m+1 60', MAX - 1_800_000, MAX - 1_800_000 + 1, 60);
run('duration rounds past: start MAX-3h, stop MAX-1h+1ms, 60', MAX - 3*H, MAX - H + 1, 60);
run('duration rounds past: start MAX-2h stop MAX-H+1 hmm', MAX - 2*H + 1, MAX - H + 2, 60);
run('stop at limit, unaligned start 15', MAX - 1_000_000, MAX, 15);
run('stop at limit, start MAX-1 15', MAX - 1, MAX, 15);
run('stop at limit, start MAX-30m 60', MAX - 1_800_000, MAX, 60);
run('stop at limit, start MAX-29m59s 60', MAX - 1_799_000, MAX, 60);
// lower end
run('lower: start -MAX', -MAX, -MAX + H, 60);
run('lower: start -MAX+step', -MAX + 900_000, -MAX + 2*900_000, 15);
run('lower: start -MAX+step-1', -MAX + 900_000 - 1, -MAX + 2*900_000, 15);
run('lower: start -MAX+2step', -MAX + 1_800_000, -MAX + 2_700_000, 15);
run('lower: start -MAX+H', -MAX + H, -MAX + 2*H, 60);
run('lower: start -MAX+1d', -MAX + 24*H, -MAX + 25*H, 60);
run('lower: one past start', -MAX - 1, -MAX + H, 60);
EOF
node probe.mts 2>&1 | head -60

