cd /tmp/w4cov-node && cat > replay.mts <<'EOF'
import { readFileSync } from 'node:fs';
import { snapSpan } from '/home/e0ipso/workspace/apps/tokkl/packages/common/snap.ts';
const src = readFileSync(process.argv[2]!, 'utf8');
const iso = (d: Date) => (Number.isNaN(d.getTime()) ? 'INVALID' : d.toISOString());
let ok = 0, bad = 0;
const str = '"([^"]*)"';
const snapsRe = new RegExp(`assertSnaps\\(${str}, ${str}, (\\d+), ${str}, ${str}, ${str}\\)`, 'g');
const rejRe = new RegExp(`assertRejected\\(${str}, ${str}, (\\d+), ${str}\\)`, 'g');
function ts(start: string, stop: string, minutes: number, tz: string): string {
  try {
    const r = snapSpan(new Date(start), new Date(stop), minutes, tz);
    return `[${iso(r.start)}, ${iso(r.stop)}]`;
  } catch (e) { return `THROWS ${(e as Error).name}`; }
}
for (const m of src.matchAll(snapsRe)) {
  const [, a, b, min, tz, es, ee] = m;
  const got = ts(a!, b!, Number(min), tz!);
  const want = `[${es}, ${ee}]`;
  if (got === want) ok++; else { bad++; console.log(`MISMATCH snaps ${a} ${b} ${min} ${tz}: node ${got}, test ${want}`); }
}
for (const m of src.matchAll(rejRe)) {
  const [, a, b, min, tz] = m;
  const got = ts(a!, b!, Number(min), tz!);
  if (got.startsWith('THROWS') || got.includes('INVALID')) { ok++; console.log(`reject ok: ${a} ${b} ${min} ${tz} -> ${got}`); }
  else { bad++; console.log(`MISMATCH rejected ${a} ${b} ${min} ${tz}: node ${got}`); }
}
console.log(`snaps calls: ${[...src.matchAll(snapsRe)].length}, rejected calls: ${[...src.matchAll(rejRe)].length}, ok ${ok}, mismatches ${bad}`);
EOF
