package com.github.e0ipso.tokkl.reports

import java.time.DayOfWeek
import java.time.LocalDate
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

/** Scratch: presets, shifting and resolutions, after range.ts. 2026-10-18 is a Sunday. */
class ReportRangeScratchTest {
    private val today = LocalDate.parse("2026-10-18")
    private fun r(from: String, to: String) = ReportRange(LocalDate.parse(from), LocalDate.parse(to))

    @Test
    fun presetsFollowTheWeekStart() {
        assertEquals(r("2026-10-12", "2026-10-18"), RangePreset.THIS_WEEK.range(today, DayOfWeek.MONDAY))
        assertEquals(r("2026-10-18", "2026-10-24"), RangePreset.THIS_WEEK.range(today, DayOfWeek.SUNDAY))
        assertEquals(r("2026-10-14", "2026-10-20"), RangePreset.THIS_WEEK.range(today, DayOfWeek.WEDNESDAY))
        assertEquals(r("2026-10-17", "2026-10-23"), RangePreset.THIS_WEEK.range(today, DayOfWeek.SATURDAY))
        assertEquals(r("2026-10-05", "2026-10-11"), RangePreset.LAST_WEEK.range(today, DayOfWeek.MONDAY))
        assertEquals(r("2026-10-11", "2026-10-17"), RangePreset.LAST_WEEK.range(today, DayOfWeek.SUNDAY))
    }

    @Test
    fun otherPresets() {
        val monday = DayOfWeek.MONDAY
        assertEquals(r("2026-10-18", "2026-10-18"), RangePreset.TODAY.range(today, monday))
        assertEquals(r("2026-10-17", "2026-10-17"), RangePreset.YESTERDAY.range(today, monday))
        assertEquals(r("2026-10-01", "2026-10-31"), RangePreset.THIS_MONTH.range(today, monday))
        assertEquals(r("2026-09-01", "2026-09-30"), RangePreset.LAST_MONTH.range(today, monday))
        assertEquals(r("2026-09-19", "2026-10-18"), RangePreset.LAST_30_DAYS.range(today, monday))
        assertEquals(r("2026-01-01", "2026-12-31"), RangePreset.THIS_YEAR.range(today, monday))
        assertEquals(r("2025-01-01", "2025-12-31"), RangePreset.LAST_YEAR.range(today, monday))
        assertEquals(r("2024-02-01", "2024-02-29"), RangePreset.THIS_MONTH.range(LocalDate.parse("2024-02-10"), monday))
        assertEquals(r("2025-12-01", "2025-12-31"), RangePreset.LAST_MONTH.range(LocalDate.parse("2026-01-03"), monday))
    }

    @Test
    fun shiftMovesWholeMonthsByMonthsAndOtherRangesByDays() {
        assertEquals(r("2026-08-01", "2026-08-31"), r("2026-09-01", "2026-09-30").shift(-1))
        assertEquals(r("2026-10-01", "2026-10-31"), r("2026-09-01", "2026-09-30").shift(1))
        assertEquals(r("2024-02-01", "2024-02-29"), r("2024-01-01", "2024-01-31").shift(1))
        assertEquals(r("2027-01-01", "2027-12-31"), r("2026-01-01", "2026-12-31").shift(1))
        assertEquals(r("2026-07-01", "2026-08-31"), r("2026-09-01", "2026-10-31").shift(-1))
        assertEquals(r("2026-10-05", "2026-10-11"), r("2026-10-12", "2026-10-18").shift(-1))
        assertEquals(r("2026-08-20", "2026-09-18"), r("2026-09-19", "2026-10-18").shift(-1))
        assertEquals(r("2026-10-17", "2026-10-17"), r("2026-10-18", "2026-10-18").shift(-1))
        // Starts on the 1st but does not end on a month's last day: moves by days.
        assertEquals(r("2026-10-11", "2026-10-20"), r("2026-10-01", "2026-10-10").shift(1))
    }

    @Test
    fun resolutionFollowsTheRangeLength() {
        assertEquals(Resolution.DAY, r("2026-01-01", "2026-03-03").resolution) // 62 days
        assertEquals(Resolution.WEEK, r("2026-01-01", "2026-03-04").resolution) // 63 days
        assertEquals(Resolution.WEEK, r("2024-01-01", "2024-12-31").resolution) // 366 days
        assertEquals(Resolution.MONTH, r("2024-01-01", "2025-01-01").resolution) // 367 days
    }

    @Test
    fun matchingPreset() {
        assertEquals(RangePreset.THIS_WEEK, RangePreset.matching(r("2026-10-12", "2026-10-18"), today, DayOfWeek.MONDAY))
        // Today and This week coincide for nobody; TODAY wins for a one-day range of today.
        assertEquals(RangePreset.TODAY, RangePreset.matching(r("2026-10-18", "2026-10-18"), today, DayOfWeek.MONDAY))
        assertNull(RangePreset.matching(r("2026-10-11", "2026-10-17"), today, DayOfWeek.MONDAY))
    }
}
