package com.github.e0ipso.tokkl.reports

import java.time.DayOfWeek
import java.time.LocalDate
import org.junit.Assert.assertEquals
import org.junit.Test

/** Scratch: the sums port totalsOf, timeSeries and groupEntries. */
class SummaryReportScratchTest {
    private fun d(s: String) = LocalDate.parse(s)
    private fun e(seconds: Long, billable: Boolean, cents: Long?, currency: String, project: Long?, name: String?, date: String) =
        ReportEntry(seconds, billable, cents, currency, project, name, if (project == null) null else "#06aaf5", d(date))

    @Test
    fun totalsSeriesAndProjects() {
        val entries = listOf(
            e(3600, true, 5000, "EUR", 1, "Web", "2026-10-12"),
            e(1800, false, null, "EUR", null, null, "2026-10-12"),
            e(900, true, 2500, "USD", 2, "Consult", "2026-10-14"),
            e(3600, true, 0, "EUR", 1, "Web", "2026-10-18"),
            e(2700, false, null, "EUR", 2, "Consult", "2026-10-18"),
        )
        val range = ReportRange(d("2026-10-12"), d("2026-10-18"))
        val report = SummaryReport.of(entries, range, DayOfWeek.MONDAY)
        assertEquals(ReportTotals(12600, 8100, 5, listOf(Amount("EUR", 5000), Amount("USD", 2500))), report.totals)
        assertEquals(null, report.currency)
        assertEquals(7, report.series.size)
        assertEquals(SeriesPoint(d("2026-10-12"), 5400, 3600), report.series[0])
        assertEquals(SeriesPoint(d("2026-10-13"), 0, 0), report.series[1])
        assertEquals(SeriesPoint(d("2026-10-14"), 900, 900), report.series[2])
        assertEquals(SeriesPoint(d("2026-10-18"), 6300, 3600), report.series[6])
        assertEquals(
            listOf(
                ProjectShare(1, "Web", "#06aaf5", 7200, 7200, 5000),
                ProjectShare(2, "Consult", "#06aaf5", 3600, 900, 2500),
                ProjectShare(null, "", null, 1800, 0, 0),
            ),
            report.projects,
        )
    }

    @Test
    fun tiesKeepTheOrderOfFirstUseAndAmountsNeedARate() {
        val entries = listOf(
            e(60, false, null, "EUR", 5, "B", "2026-10-12"),
            e(60, false, null, "EUR", 4, "A", "2026-10-12"),
        )
        val report = SummaryReport.of(entries, ReportRange(d("2026-10-12"), d("2026-10-12")), DayOfWeek.MONDAY)
        assertEquals(listOf(5L, 4L), report.projects.map { it.id })
        assertEquals(emptyList<Amount>(), report.totals.amounts)
    }

    @Test
    fun weekBucketsStartOnTheWeekStartAndOutsideEntriesCountNowhere() {
        val range = ReportRange(d("2026-01-01"), d("2026-03-31")) // 90 days: weeks
        val entries = listOf(
            e(100, true, null, "EUR", 1, "W", "2026-01-01"),
            e(200, false, null, "EUR", 1, "W", "2026-01-05"),
            e(400, false, null, "EUR", 1, "W", "2026-04-02"), // after the last bucket
        )
        val report = SummaryReport.of(entries, range, DayOfWeek.MONDAY)
        assertEquals(Resolution.WEEK, report.resolution)
        assertEquals(d("2025-12-29"), report.series.first().start)
        assertEquals(SeriesPoint(d("2025-12-29"), 100, 100), report.series[0])
        assertEquals(SeriesPoint(d("2026-01-05"), 200, 0), report.series[1])
        assertEquals(d("2026-03-30"), report.series.last().start)
        assertEquals(14, report.series.size)
        // Totals still count every entry the server sent, as totalsOf does.
        assertEquals(700, report.totals.seconds)
    }
}
