        ConfiguredTrust.readFrom(InMemoryServerTrust())
        server.close()
    }

    private fun json(body: String, vararg headers: Pair<String, String>) =
        MockResponse.Builder().code(200).body(body).addHeader("Content-Type", "application/json").apply {
            for ((k, v) in headers) addHeader(k, v)
        }.build()

    @Test
    fun workspaceReadsMeThenTheWorkspaceRounding() {
        server.enqueue(json("""{"id":1,"default_workspace_id":7,"timezone":"UTC","beginning_of_week":1}"""))
        server.enqueue(json("""{"id":7,"rounding":1,"rounding_minutes":15,"default_currency":"EUR"}"""))
        assertEquals(ApiResult.Success(ReportWorkspace(7, 1, 15)), reports.workspace())
        assertEquals("/api/v9/me", server.takeRequest().url.encodedPath)
        assertEquals("/api/v9/workspaces/7", server.takeRequest().url.encodedPath)
    }

    @Test
    fun entriesFollowTheNextRowHeaderAndDateInTheZone() {
        val row = { id: Int, start: String, amount: String ->
            """{"user_id":1,"username":"A","email":"a@x","project_id":3,"project_name":"Web","project_color":"#06aaf5","project_hex":"#06aaf5",
            "client_name":null,"task_id":null,"task_name":null,"description":"d","billable":true,"tag_ids":[],"tag_names":[],
            "hourly_rate_in_cents":5000,"billable_amount_in_cents":$amount,"currency":"EUR","row_number":$id,
            "time_entries":[{"id":$id,"seconds":900,"start":"$start","stop":"x","at":"y"}]}"""
        }
        server.enqueue(json("[" + row(1, "2026-10-17T10:30:00+00:00", "1250") + "]", "X-Next-Row-Number" to "2"))
        server.enqueue(json("[" + row(2, "2026-10-18T09:59:59+00:00", "null") + "]"))
        val ws = ReportWorkspace(7, -1, 30)
        val range = ReportRange(LocalDate.parse("2026-10-12"), LocalDate.parse("2026-10-18"))
        val answer = reports.entries(ws, range, ZoneId.of("Pacific/Kiritimati"))
        assertTrue(answer is ApiResult.Success)
        val entries = (answer as ApiResult.Success).value
        assertEquals(2, entries.size)
        // 10:30 UTC is 00:30 the next day at UTC+14.
        assertEquals(LocalDate.parse("2026-10-18"), entries[0].date)
        assertEquals(LocalDate.parse("2026-10-18"), entries[1].date)
        assertEquals(1250L, entries[0].amountCents)
        assertEquals(null, entries[1].amountCents)
        val first = Json.parseToJsonElement(server.takeRequest().body!!.utf8()).jsonObject
        assertEquals("2026-10-12", first["start_date"]!!.jsonPrimitive.content)
        assertEquals("2026-10-18", first["end_date"]!!.jsonPrimitive.content)
        assertEquals(-1, first["rounding"]!!.jsonPrimitive.int)
        assertEquals(30, first["rounding_minutes"]!!.jsonPrimitive.int)
        assertEquals("ASC", first["order_dir"]!!.jsonPrimitive.content)
        assertEquals(1, first["first_row_number"]!!.jsonPrimitive.int)
        val second = server.takeRequest()
        assertEquals("/reports/api/v3/workspace/7/search/time_entries", second.url.encodedPath)
        assertEquals(2, Json.parseToJsonElement(second.body!!.utf8()).jsonObject["first_row_number"]!!.jsonPrimitive.int)
    }

    @Test
    fun aNextRowThatDoesNotMoveIsRefused() {
        server.enqueue(json("[]", "X-Next-Row-Number" to "1"))
        val answer = reports.entries(ReportWorkspace(7, 0, 0), ReportRange(LocalDate.parse("2026-10-12"), LocalDate.parse("2026-10-12")), ZoneId.of("UTC"))
        assertTrue((answer as ApiResult.Failure).error is ApiError.InvalidResponse)
    }

    @Test
    fun aBadStartIsAnInvalidResponse() {
        server.enqueue(json("""[{"billable":false,"currency":"EUR","time_entries":[{"seconds":1,"start":"yesterday"}]}]"""))
        val answer = reports.entries(ReportWorkspace(7, 0, 0), ReportRange(LocalDate.parse("2026-10-12"), LocalDate.parse("2026-10-12")), ZoneId.of("UTC"))
        assertTrue((answer as ApiResult.Failure).error is ApiError.InvalidResponse)
    }
}
