/**
 * Scratch, not committed: the reports screen against the real Tokkl container, with an account
 * whose timezone (UTC+14) and week start (Wednesday) differ from the emulator's. Compares the
 * app's summary with POST /api/app/report, the web app's own call, and saves screenshots.
 */
class ReportsLiveScratchTest {
    @get:Rule(order = 0)
    val session = SessionRule()

    @get:Rule(order = 1)
    val compose = createEmptyComposeRule()

    private val instrumentation = InstrumentationRegistry.getInstrumentation()
    private val context = instrumentation.targetContext
    private val app get() = context.applicationContext as TokklApplication
    private lateinit var account: TestAccounts.Account
    private lateinit var seed: Seed
    private var scenario: ActivityScenario<MainActivity>? = null
    private var fontScaleBefore: String? = null

    @Before
    fun setUp() {
        DeviceShell.run("mkdir -p $SHOTS")
        account = TestAccounts.create(timezone = ZONE)
        seed = Seed(account.client)
[credential-related line omitted]
        runBlocking { app.accountSettings.refresh().join() }
        val settings = app.accountSettings.state.value!!
        assertEquals(ZONE, settings.timeZone)
        assertEquals(DayOfWeek.WEDNESDAY, settings.beginningOfWeek)
        assertEquals("classic", settings.durationFormat.togglName)
    }

    @After
    fun tearDown() {
        try {
            scenario?.close()
        } finally {
            try {
                DeviceShell.run("cmd connectivity airplane-mode disable")
                awaitNetwork(on = true)
            } finally {
                try {
                    fontScaleBefore?.let { setFontScale(it) }
                } finally {
                    try {
                        if (::account.isInitialized) TestAccounts.delete(account)
                    } finally {
                        ThemeSettingsStore(context).clear()
                        followTheSystemNightMode()
                        SessionRule.signOut()
                    }
                }
            }
        }
    }

    @Test
    fun light1x() = look(ThemeMode.LIGHT, "1.0", "light-1.0", parity = true)

    @Test
    fun dark1x() = look(ThemeMode.DARK, "1.0", "dark-1.0", parity = false)

    @Test
    fun light2x() = look(ThemeMode.LIGHT, "2.0", "light-2.0", parity = false, dialogs = true)

    @Test
    fun dark2x() = look(ThemeMode.DARK, "2.0", "dark-2.0", parity = false)

    @Test
    fun offlineShowsTheMessageAndNoNumbers() {
        launch(ThemeMode.LIGHT)
        openReports()
