                listOf(g["id"]!!.jsonPrimitive.longOrNull, g["title"]!!.jsonPrimitive.content, g["seconds"]!!.jsonPrimitive.long, g["billable_seconds"]!!.jsonPrimitive.long, g["amount_cents"]!!.jsonPrimitive.long)
            },
            report.projects.map { listOf(it.id, it.title, it.seconds, it.billableSeconds, it.amountCents) },
        )
        // The seed: four entries this week, rounded up to 15 minutes, in two currencies.
        assertEquals(4, report.totals.entryCount)
        assertEquals(1800L + 4500 + 900 + 1800, report.totals.seconds)
        assertEquals(listOf("EUR" to 2000L, "USD" to 12500L), report.totals.amounts.map { it.currency to it.cents })
        val todayPoint = report.series.single { it.start == seed.today }
        assertTrue("the 00:10 entry counts on today in the account's zone: $todayPoint", todayPoint.seconds >= 900)
    }

    private fun assertUi(report: SummaryReport) {
        val settings = settings()
        val resources = context.resources
        val words = DateWords(resources)
        val time = settings.time()!!
        awaitText(string(R.string.reports_preset_this_week))
        compose.onNode(hasText(words.range(report.range, time.today()), substring = true)).assertExists()
        compose.onNode(hasText(settings.formatDuration(report.totals.seconds))).assertExists()
        val description = compose.onNode(hasContentDescription("Bar chart of time per day", substring = true))
            .fetchSemanticsNode().config.getOrNull(SemanticsProperties.ContentDescription)!!.joinToString()
        println("SCRATCH chart description: $description")
        for (point in report.series) {
            val spoken = "${words.bucket(point.start, Resolution.DAY)}: ${spokenDuration(resources, point.seconds)}"
            assertTrue("chart description reads $spoken", description.contains(spoken))
        }
        for (project in report.projects) {
            val title = project.title.ifBlank { string(R.string.reports_without_project) }
            compose.onNode(hasText(title, substring = true)).performScrollTo().assertExists()
        }
        if (report.totals.amounts.size > 1) compose.onNode(hasText(string(R.string.reports_mixed_currencies))).performScrollTo()
    }

    /** No text node is cut off or leaves the screen's width. */
    private fun assertTextsFit() {
        val root = compose.onRoot().fetchSemanticsNode().boundsInRoot
        val texts = compose.onAllNodes(SemanticsMatcher.keyIsDefined(SemanticsProperties.Text), useUnmergedTree = true).fetchSemanticsNodes()
        for (node in texts) {
            val text = node.config.getOrNull(SemanticsProperties.Text)?.joinToString() ?: continue
            val layouts = mutableListOf<TextLayoutResult>()
            node.config.getOrNull(SemanticsActions.GetTextLayoutResult)?.action?.invoke(layouts)
            layouts.firstOrNull()?.let { assertFalse("cut off: $text", it.didOverflowHeight) }
            val box = node.boundsInRoot
            assertTrue("leaves the screen's width: $text $box $root", box.left >= root.left - 1 && box.right <= root.right + 1)
        }
    }

    /** Every clickable node has a label TalkBack reads. */
    private fun assertControlsLabelled() {
        for (node in compose.onAllNodes(hasClickAction()).fetchSemanticsNodes()) {
            val text = node.config.getOrNull(SemanticsProperties.Text)?.joinToString().orEmpty()
            val description = node.config.getOrNull(SemanticsProperties.ContentDescription)?.joinToString().orEmpty()
            assertTrue("a control without a label: ${node.config}", text.isNotBlank() || description.isNotBlank())
        }
    }

    private fun assertNoNumbers(report: SummaryReport) {
        val settings = settings()
        for (value in listOf(report.totals.seconds, report.totals.billableSeconds) + report.series.map { it.seconds }.filter { it > 0 }) {
            assertTrue("no ${settings.formatDuration(value)} offline", compose.onAllNodes(hasText(settings.formatDuration(value), substring = true)).fetchSemanticsNodes().isEmpty())
        }
        assertTrue("no totals offline", compose.onAllNodes(hasText(string(R.string.reports_total_time).uppercase())).fetchSemanticsNodes().isEmpty())
        assertTrue("no chart offline", compose.onAllNodes(hasContentDescription("Bar chart", substring = true)).fetchSemanticsNodes().isEmpty())
    }

    private fun launch(mode: ThemeMode) {
        ThemeSettingsStore(context).save(ThemeSettings(mode = mode))
        scenario = ActivityScenario.launch(MainActivity::class.java)
    }

    private fun openReports() {
        awaitText(string(R.string.reports))
        compose.onNode(hasText(string(R.string.reports)) and hasClickAction()).performClick()
    }

    private fun loadedReport(): SummaryReport {
        compose.waitUntil(30_000) { modelState() !is ReportsState.Loading && modelState() != ReportsState.Closed }
        val state = modelState()
        assertTrue("loaded: $state", state is ReportsState.Loaded)
        compose.waitForIdle()
        return (state as ReportsState.Loaded).report
    }

    private fun modelState(): ReportsState {
        var state: ReportsState? = null
        scenario!!.onActivity { state = ViewModelProvider(it)[ReportsViewModel::class.java].model.state.value }
        return state!!
    }

    private fun settings() = app.accountSettings.state.value!!

    private fun awaitText(text: String) =
        compose.waitUntil("\"$text\" shows", 30_000) { compose.onAllNodes(hasText(text, substring = true)).fetchSemanticsNodes().isNotEmpty() }

    private fun shots(name: String) {
        compose.onNode(hasScrollAction()).performTouchInput { repeat(6) { swipeDown() } }
        for (i in 1..12) {
            settle()
            shot("$name-$i")
            val range = compose.onNode(hasScrollAction()).fetchSemanticsNode().config.getOrNull(SemanticsProperties.VerticalScrollAxisRange) ?: break
            if (range.value() >= range.maxValue()) break
            compose.onNode(hasScrollAction()).performTouchInput { swipeUp(durationMillis = 600) }
        }
    }

    private fun settle() {
        compose.waitForIdle()
        Thread.sleep(700)
    }

    private fun shot(name: String) {
        DeviceShell.run("screencap -p $SHOTS/$name.png")
    }

    private fun setFontScale(scale: String) {
        DeviceShell.run("settings put system font_scale $scale")
        val expected = scale.toFloatOrNull() ?: 1f
        val deadline = System.nanoTime() + 10_000_000_000L
        while (context.resources.configuration.fontScale != expected) {
            check(System.nanoTime() < deadline) { "font scale ${context.resources.configuration.fontScale}" }
            Thread.sleep(50)
        }
    }

    private fun awaitNetwork(on: Boolean) {
        val deadline = System.nanoTime() + 30_000_000_000L
        while (true) {
            val result = account.client.get(account.client.server.api("me"), JsonObject.serializer())
            val answers = (result as? ApiResult.Failure)?.error !is ApiError.Network
            if (answers == on) return
            check(System.nanoTime() < deadline) { "network did not turn ${if (on) "on" else "off"}" }
            Thread.sleep(200)
        }
    }

    /** Every file of the app's private and external storage, with its size and change time. */
    private fun snapshot(): Map<String, Pair<Long, Long>> {
        val roots = listOfNotNull(context.dataDir, context.getExternalFilesDir(null)?.parentFile)
        return roots.flatMap { root -> root.walkTopDown().filter(File::isFile).map { it.path to (it.length() to it.lastModified()) } }.toMap()
    }

    private fun string(id: Int): String = context.getString(id)

    private class Seed(private val api: TogglApiClient) {
        val zone: ZoneId = ZoneId.of(ZONE)
        val today: LocalDate = LocalDate.now(zone)
        val weekStart: LocalDate = today.with(TemporalAdjusters.previousOrSame(DayOfWeek.WEDNESDAY))
        val workspace = api.get(api.server.api("me"), MeIds.serializer()).orFail("GET /api/v9/me").defaultWorkspaceId

        init {
            api.send("PUT", api.server.api("me"), buildJsonObject { put("beginning_of_week", 3) }, JsonObject.serializer()).orFail("PUT /me")
            api.send(
                "PUT",
                api.server.api("workspaces", workspace.toString()),
                buildJsonObject {
                    put("rounding", 1)
                    put("rounding_minutes", 15)
                    put("default_hourly_rate", 40)
                    put("default_currency", "EUR")
                },
                JsonObject.serializer(),
            ).orFail("PUT workspace")
            api.send("POST", api.server.api("me", "preferences"), buildJsonObject { put("duration_format", "classic") }, JsonObject.serializer())
                .orFail("POST /me/preferences")
        }

        val website = project(buildJsonObject { put("name", "Website"); put("color", "#06aaf5"); put("billable", true) })
        val consulting = project(buildJsonObject { put("name", "Consulting"); put("color", "#c7af14"); put("billable", true); put("rate", 100); put("currency", "USD") })
        val internal = project(buildJsonObject { put("name", "Internal"); put("color", "#990099") })

        init {
            entry(day(0).atTime(9, 0), 1000, website, billable = true)
            entry(day(1).atTime(14, 0), 3700, consulting, billable = true)
            entry(today.atTime(0, 10), 600, null, billable = false)
            entry(day(2).atTime(if (day(2) == today) 0 else 23, if (day(2) == today) 30 else 50), 1200, internal, billable = false)
            entry(weekStart.minusDays(1).atTime(12, 0), 3600, website, billable = true)
        }

        fun day(i: Long): LocalDate = minOf(weekStart.plusDays(i), today)

        private fun project(body: JsonObject): Long =
            api.send("POST", api.server.api("workspaces", workspace.toString(), "projects"), body, Created.serializer()).orFail("POST project").id

        private fun entry(start: LocalDateTime, seconds: Int, project: Long?, billable: Boolean) {
            val body = buildJsonObject {
                put("workspace_id", workspace)
                put("created_with", "tokkl-android scratch")
                put("description", "Scratch")
                put("start", start.atZone(zone).toInstant().toString())
                put("duration", seconds)
                if (project != null) put("project_id", project)
                put("billable", billable)
            }
            api.send("POST", api.server.api("workspaces", workspace.toString(), "time_entries"), body, Created.serializer()).orFail("POST entry")
        }
    }

    @Serializable
    private class MeIds(@SerialName("default_workspace_id") val defaultWorkspaceId: Long)

    @Serializable
    private class Created(val id: Long)

    private companion object {
        /** UTC+14 all year, so its day differs from UTC's for ten hours of every day. */
        const val ZONE = "Pacific/Kiritimati"
        const val SHOTS = "/data/local/tmp/tokkl-shots"
    }
}
