mkdir -p /tmp/tka-0070-diff && cd /tmp/tka-0070-diff && cat > Gen.java <<'EOF'
import java.time.*;
import java.time.zone.*;
import java.util.*;

// Writes snapSpan inputs as TSV: startMs, stopMs, minutes, zone, category.
public class Gen {
    static final long MIN = 60_000L, HOUR = 3_600_000L, DAY = 86_400_000L;
    static final long MAX = 8_640_000_000_000_000L;
    static final double[] RES = {1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30, 60};
    static final String[] ZONES = {
        "UTC", "Europe/Madrid", "Europe/London", "Europe/Dublin", "Europe/Moscow", "America/New_York",
        "America/Santiago", "America/Sao_Paulo", "America/St_Johns", "America/Havana", "America/Asuncion",
        "Australia/Lord_Howe", "Australia/Adelaide", "Pacific/Chatham", "Pacific/Apia", "Pacific/Kiritimati",
        "Asia/Kolkata", "Asia/Kathmandu", "Asia/Tehran", "Asia/Gaza", "Antarctica/Troll", "Africa/Casablanca",
        "America/Caracas", "Asia/Pyongyang", "Pacific/Marquesas",
    };
    static Random rnd = new Random(70);
    static StringBuilder out = new StringBuilder();

    static long span() {
        switch (rnd.nextInt(5)) {
            case 0: return 0;
            case 1: return rnd.nextLong(6 * HOUR);
            case 2: return (long) RES[rnd.nextInt(RES.length)] * MIN * rnd.nextInt(20);
            case 3: return rnd.nextLong(3 * DAY);
            default: return rnd.nextLong(2 * MIN);
        }
    }

    static void emit(long start, long stop, double minutes, String zone, String cat) {
        out.append(start).append('\t').append(stop).append('\t').append(minutes).append('\t')
            .append(zone).append('\t').append(cat).append('\n');
    }

    public static void main(String[] args) {
        long from = Instant.parse("1900-01-01T00:00:00Z").toEpochMilli();
        long to = Instant.parse("2045-01-01T00:00:00Z").toEpochMilli();
        for (String zone : ZONES) {
            ZoneRules rules = ZoneId.of(zone).getRules();
            ZoneOffsetTransition t = rules.nextTransition(Instant.ofEpochMilli(from));
            while (t != null && t.getInstant().toEpochMilli() < to) {
                long at = t.getInstant().toEpochMilli();
                for (int i = 0; i < 6; i++) {
                    long start = at + rnd.nextLong(-3 * HOUR, 3 * HOUR);
                    emit(start, start + span(), RES[rnd.nextInt(RES.length)], zone, "transition");
                }
                // Starts on whole seconds and on half steps near the change, where ties happen.
                double minutes = RES[rnd.nextInt(RES.length)];
                long half = (long) (minutes * MIN / 2);
                for (long k = -8; k <= 8; k++) {
                    long start = at + k * half + (rnd.nextBoolean() ? 0 : rnd.nextLong(-2, 3) * 1000);
                    emit(start, start + span(), minutes, zone, "transition-tie");
                }
                t = rules.nextTransition(t.getInstant());
            }
            long lo = Instant.parse("1700-01-01T00:00:00Z").toEpochMilli();
            long hi = Instant.parse("2200-01-01T00:00:00Z").toEpochMilli();
            for (int i = 0; i < 2000; i++) {
                long start = rnd.nextLong(lo, hi);
                if (rnd.nextBoolean()) start -= Math.floorMod(start, 30_000L);
                emit(start, start + span(), RES[rnd.nextInt(RES.length)], zone, "uniform");
            }
            // Years 1 to 99 and before the common era, where time.ts reads the year back oddly.
            long y1 = Instant.parse("0001-01-01T00:00:00Z").toEpochMilli();
            long y100 = Instant.parse("0100-01-01T00:00:00Z").toEpochMilli();
            for (int i = 0; i < 300; i++) {
                long start = rnd.nextLong(y1 - 50_000L * 365 * DAY, y100 + DAY);
                if (rnd.nextBoolean()) start = rnd.nextLong(y1 - 5 * DAY, y1 + 5 * DAY);
                if (rnd.nextInt(4) == 0) start = rnd.nextLong(y100 - 5 * DAY, y100 + 5 * DAY);
                emit(start, start + span(), RES[rnd.nextInt(RES.length)], zone, "ancient");
            }
            // Both ends of a JavaScript Date's range.
            for (int i = 0; i < 200; i++) {
                double minutes = RES[rnd.nextInt(RES.length)];
                long start = MAX - rnd.nextLong(0, 4 * HOUR);
                emit(start, Math.min(start + span(), MAX + rnd.nextLong(0, 3) * 1000), minutes, zone, "edge-max");
                long s2 = -MAX + rnd.nextLong(-2000, 4 * HOUR);
                emit(s2, s2 + span(), minutes, zone, "edge-min");
            }
        }
        // Resolutions that are not valid, and a stop before the start.
        for (double m : new double[] {0, -5, 7, 45, 90, 120, 2.5, Double.NaN, 0.5}) {
            emit(1_760_000_000_000L, 1_760_000_900_000L, m, "UTC", "bad-resolution");
        }
        emit(1_760_000_900_000L, 1_760_000_000_000L, 15, "UTC", "reversed");
        System.out.print(out);
    }
}
EOF
cat > run.mts <<'EOF'
// Runs Tokkl's snapSpan over the TSV inputs; the snap.ts path comes in as the first argument.
import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

const [snapPath, inputPath] = process.argv.slice(2);
const { snapSpan, isTimeResolution } = await import(pathToFileURL(snapPath).href);

const wholeSeconds = (t: number) => new Date(Math.floor(t / 1000) * 1000);
function run(start: Date, stop: Date, minutes: number, zone: string): string {
  try {
    const span = snapSpan(start, stop, minutes, zone);
    return `${span.start.getTime()}\t${span.stop.getTime()}`;
  } catch (error) {
    return `E\t${(error as Error).name}: ${(error as Error).message}`;
  }
}

const lines: string[] = [];
for (const line of readFileSync(inputPath, 'utf8').split('\n')) {
  if (!line) continue;
  const [start, stop, minutes, zone] = line.split('\t');
  const s = Number(start), t = Number(stop), m = Number(minutes);
  const raw = run(new Date(s), new Date(t), m, zone!);
  const server = isTimeResolution(m) ? run(wholeSeconds(s), wholeSeconds(t), m, zone!) : 'skip\t';
  lines.push(`${raw}\t${server}`);
}
process.stdout.write(lines.join('\n') + '\n');
EOF
java Gen.java > inputs.tsv; echo "gen exit=$?"; wc -l inputs.tsv; cut -f5 inputs.tsv | sort | uniq -c

