import com.github.e0ipso.tokkl.time.SnapKt;
import com.github.e0ipso.tokkl.time.SnappedSpan;
import java.nio.file.*;
import java.time.*;
import java.util.*;

// Compares the Kotlin port with the TypeScript results: Cmp inputs.tsv ts.tsv
public class Cmp {
    static String kotlin(long start, long stop, double minutes, String zone, boolean unsent) {
        try {
            SnappedSpan span = unsent
                ? SnapKt.snapUnsent(Instant.ofEpochMilli(start), Instant.ofEpochMilli(stop), minutes, ZoneId.of(zone))
                : SnapKt.snapSpan(Instant.ofEpochMilli(start), Instant.ofEpochMilli(stop), minutes, ZoneId.of(zone));
            return span.getStart().toEpochMilli() + "\t" + span.getStop().toEpochMilli();
        } catch (IllegalArgumentException e) {
            return "E\t" + e.getMessage();
        }
    }

    public static void main(String[] args) throws Exception {
        List<String> in = Files.readAllLines(Path.of(args[0]));
        List<String> ts = Files.readAllLines(Path.of(args[1]));
        Map<String, Integer> agree = new TreeMap<>(), differ = new TreeMap<>(), departs = new TreeMap<>();
        int shown = 0;
        for (int i = 0; i < in.size(); i++) {
            String[] a = in.get(i).split("\t");
            String[] t = ts.get(i).split("\t", -1);
            long start = Long.parseLong(a[0]), stop = Long.parseLong(a[1]);
            double minutes = Double.parseDouble(a[2]);
            String cat = a[4];
            String[][] pairs = {
                {"snapSpan", t[0] + "\t" + t[1], kotlin(start, stop, minutes, a[3], false)},
                {"snapUnsent", t[2] + "\t" + t[3], t[2].equals("skip") ? "skip\t" : kotlin(start, stop, minutes, a[3], true)},
            };
            for (String[] p : pairs) {
                String key = p[0] + " " + cat;
                String want = p[1], got = p[2];
                boolean same;
                if (want.startsWith("E\t")) {
                    String msg = want.substring(want.indexOf(": ") + 2);
                    same = got.equals("E\t" + msg) || (got.startsWith("E\t") && msg.startsWith("Invalid time resolution"));
                } else {
                    same = want.equals(got);
                }
                if (same) { agree.merge(key, 1, Integer::sum); continue; }
                // The documented departure: the TypeScript returns an invalid stop, the port throws.
                if (want.endsWith("\tNaN") && got.equals("E\tInvalid time value")) { departs.merge(key, 1, Integer::sum); continue; }
                differ.merge(key, 1, Integer::sum);
                if (shown++ < 15) System.out.println("DIFF " + key + " in=" + in.get(i) + " ts=" + want.replace('\t', ' ') + " kt=" + got.replace('\t', ' '));
            }
        }
        System.out.println("agree " + agree);
        System.out.println("departs (TS invalid stop, port throws) " + departs);
        System.out.println("differ " + differ);
        System.out.println("total agree=" + agree.values().stream().mapToInt(x -> x).sum()
            + " departs=" + departs.values().stream().mapToInt(x -> x).sum()
            + " differ=" + differ.values().stream().mapToInt(x -> x).sum());
    }
}
EOF
