import com.github.e0ipso.tokkl.time.TimeZoneKt;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.*;
import java.util.*;

// Compares parseTimeZone with Intl: ZoneCmp names.txt instants.txt intl-zones.txt
public class ZoneCmp {
    public static void main(String[] a) throws Exception {
        String[] names = new String(Files.readAllBytes(Path.of(a[0])), StandardCharsets.UTF_8).split("\n", -1);
        List<String> instantLines = Files.readAllLines(Path.of(a[1]));
        long[] instants = instantLines.stream().mapToLong(Long::parseLong).toArray();
        int oldCount = 200;
        List<String> intl = Files.readAllLines(Path.of(a[2]), StandardCharsets.UTF_8);
        Map<String, List<String>> buckets = new TreeMap<>();
        for (int i = 0; i < intl.size(); i++) {
            String name = names[i];
            ZoneId zone = TimeZoneKt.parseTimeZone(name);
            String want = intl.get(i);
            String bucket;
            if (want.equals("REJECT")) {
                bucket = zone == null ? "both reject" : "PORT ACCEPTS, INTL REJECTS";
            } else if (zone == null) {
                bucket = "intl accepts, port null";
            } else {
                String[] w = want.split(",");
                boolean oldDiff = false, newDiff = false;
                for (int k = 0; k < instants.length; k++) {
                    long got = zone.getRules().getOffset(Instant.ofEpochMilli(instants[k])).getTotalSeconds();
                    if (!w[k].equals(Long.toString(got))) { if (k < oldCount) oldDiff = true; else newDiff = true; }
                }
                bucket = newDiff ? "OFFSETS DIFFER 1970-2040" : oldDiff ? "offsets differ before 1970 only" : "same offsets";
            }
            buckets.computeIfAbsent(bucket, k -> new ArrayList<>()).add(name + (zone == null ? "" : "=" + zone.getId()));
        }
        for (var e : buckets.entrySet()) {
            List<String> v = e.getValue();
            System.out.println(e.getKey() + ": " + v.size());
            if (!e.getKey().equals("same offsets") && !e.getKey().equals("both reject")) {
                System.out.println("  " + String.join(" | ", v.subList(0, Math.min(v.size(), 60))).replace("\u0000", "\\0"));
            }
        }
    }
}
EOF
