/** Disposable verification for TKA-0029; not committed. */
class HistoryScratchTest {
    private val madrid = ZoneId.of("Europe/Madrid")
    private val now = Instant.parse("2026-10-15T10:00:00Z")
    private val clock = Clock.fixed(now, ZoneOffset.UTC)
    private fun time(resolution: Double?) = AccountTime(madrid, DayOfWeek.MONDAY, resolution, clock)

    private fun entry(id: Long, start: String, stop: String?, project: Long? = null) = CachedTimeEntry(
        id, 1, project, null, "e$id", Instant.parse(start), stop?.let(Instant::parse), false, emptyList(), emptyList(),
    )

    @Test
    fun groupsByAccountDayNewestFirstWithTotalsAndLeavesOutRunning() {
        val days = historyDays(
            cached = listOf(
                EntryWithSendState(entry(1, "2026-10-14T22:30:00Z", "2026-10-14T23:00:00Z"), false), // 00:30 on 15th in Madrid
                EntryWithSendState(entry(2, "2026-10-14T21:00:00Z", "2026-10-14T21:45:30.900Z"), false), // 23:00 on 14th
                EntryWithSendState(entry(3, "2026-10-15T08:00:00Z", null), false), // running
                EntryWithSendState(entry(4, "2026-10-15T06:00:00Z", "2026-10-15T07:00:00Z", project = 9), false),
            ),
            older = emptyList(),
            projects = listOf(CachedProject(9, 1, null, "P", "#0b83d9", true, false)),
            tasks = emptyList(),
            time = time(15.0),
        )
        assertEquals(listOf(LocalDate.of(2026, 10, 15), LocalDate.of(2026, 10, 14)), days.map { it.date })
        assertEquals(listOf(4L, 1L), days[0].entries.map { it.id })
        assertEquals(3600L + 1800L, days[0].totalSeconds)
        assertEquals(2730L, days[1].totalSeconds)
        assertEquals("P", days[0].entries[0].project)
        // Sent entries keep the server's times even with a resolution.
        assertEquals(Instant.parse("2026-10-14T21:45:30.900Z"), days[1].entries[0].stop)
    }

    @Test
    fun unsentEntriesShowSnapUnsentAndSentOnesDoNot() {
        val raw = entry(5, "2026-10-15T07:07:31.500Z", "2026-10-15T08:01:02.250Z")
        val snapped = time(15.0).snapUnsent(raw.start, raw.stop!!)
        val unsent = historyDays(listOf(EntryWithSendState(raw, true)), emptyList(), emptyList(), emptyList(), time(15.0))
        assertEquals(snapped.start, unsent.single().entries.single().start)
        assertEquals(snapped.stop, unsent.single().entries.single().stop)
        assertEquals(Instant.parse("2026-10-15T07:00:00Z"), snapped.start)
        assertTrue(unsent.single().entries.single().unsent)
        val noResolution = historyDays(listOf(EntryWithSendState(raw, true)), emptyList(), emptyList(), emptyList(), time(null))
        assertEquals(raw.start, noResolution.single().entries.single().start)
        assertEquals(raw.stop, noResolution.single().entries.single().stop)
    }

    @Test
