    private fun segment(label: Int) = composeRule.onNode(hasText(context.getString(label)) and isSelectable())

    private fun awaitSelected(label: Int) = waitUntil("${context.getString(label)} selected") {
        composeRule.onAllNodes(hasText(context.getString(label)) and isSelectable() and isSelected()).fetchSemanticsNodes().isNotEmpty()
    }

    private fun awaitText(text: String) = waitUntil(text) {
        composeRule.onAllNodes(hasText(text), useUnmergedTree = true).fetchSemanticsNodes().isNotEmpty()
    }

    private fun waitUntil(what: String, condition: () -> Boolean) = composeRule.waitUntil(what, 30_000) { condition() }

    private fun signIn(server: ServerUrl, token: String) {
        ServerTrustStore(context).confirmCleartext(server)
        Session(context).save(server, token)
    }

    private fun setAirplaneMode(on: Boolean) {
        DeviceShell.run("cmd connectivity airplane-mode ${if (on) "enable" else "disable"}")
        val deadline = System.nanoTime() + 30_000_000_000L
        while (serverAnswers() == on) {
            if (System.nanoTime() > deadline) throw AssertionError("network did not switch")
            Thread.sleep(200)
        }
    }

    private fun serverAnswers(): Boolean {
        val result = web.get(web.server.api("me"), JsonObject.serializer())
        return (result as? ApiResult.Failure)?.error !is ApiError.Network
    }

    private companion object {
        const val TAG = "TimerViewScratch"
    }
}
