package com.github.e0ipso.tokkl.ui.brandcapture

import android.util.Log
import androidx.compose.foundation.background
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.padding
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.PixelMap
import androidx.compose.ui.graphics.toPixelMap
import androidx.compose.ui.platform.testTag
import androidx.compose.ui.test.captureToImage
import androidx.compose.ui.test.junit4.v2.createComposeRule
import androidx.compose.ui.test.onNodeWithTag
import androidx.compose.ui.unit.dp
import com.github.e0ipso.tokkl.ui.Brand
import com.github.e0ipso.tokkl.ui.BrandSize
import com.github.e0ipso.tokkl.ui.theme.TokklDarkColorScheme
import com.github.e0ipso.tokkl.ui.theme.TokklTheme
import kotlin.math.abs
import kotlin.math.roundToInt
import org.junit.Rule
import org.junit.Test

/** Disposable diagnostics for TKA-0152: which pixels BrandTest's light-mode check rejects. Not committed. */
class BrandHaloScratch {
    @get:Rule
    val composeRule = createComposeRule()

    @Test
    fun lightModeStrays() {
        var look by mutableStateOf(0)
        val bg = TokklDarkColorScheme.background
        val marker = Color(0xFFFF00FF)
        composeRule.setContent {
            Box(Modifier.testTag("f").background(if (look == 2) marker else bg).padding(8.dp)) {
                TokklTheme(darkTheme = look == 0) { Brand(BrandSize.LARGE) }
            }
        }
        look = 1
        val light = capture()
        look = 2
        val onMarker = capture()
        val lines = mutableListOf<String>()
        var count = 0
        for (x in 0 until onMarker.width) for (y in 0 until onMarker.height) {
            if (near(onMarker[x, y], marker) && !near(light[x, y], bg)) {
                count++
                if (lines.size < 40) lines += "($x,$y) light=${hex(light[x, y])} marker=${hex(onMarker[x, y])}"
            }
        }
        Log.i("BrandHaloScratch", "size ${onMarker.width}x${onMarker.height} strays $count")
        lines.forEach { Log.i("BrandHaloScratch", it) }
        throw AssertionError("strays $count: " + lines.joinToString("; "))
    }

    private fun capture(): PixelMap {
        composeRule.waitForIdle()
        return composeRule.onNodeWithTag("f").captureToImage().toPixelMap()
    }

    private fun c8(v: Float) = (v * 255).roundToInt()
    private fun near(a: Color, b: Color) =
        abs(c8(a.red) - c8(b.red)) <= 2 && abs(c8(a.green) - c8(b.green)) <= 2 && abs(c8(a.blue) - c8(b.blue)) <= 2
    private fun hex(c: Color) = "%02x%02x%02x".format(c8(c.red), c8(c.green), c8(c.blue))
}
