#!/usr/bin/env bash
# Helpers for screenshots on emulator-5554. Source it.
A=(adb -s emulator-5554)
SHOTS=/tmp/sift-w6-e4/shots
mkdir -p "$SHOTS"
# Waits until the screen's view hierarchy holds $1 (at most 30 s).
await_text() {
  local deadline=$((SECONDS + 30))
  until "${A[@]}" exec-out uiautomator dump /dev/tty 2>/dev/null | grep -qF "$1"; do
    [ "$SECONDS" -ge "$deadline" ] && { echo "timeout waiting for: $1" >&2; return 1; }
    sleep 1
  done
}
shot() { "${A[@]}" exec-out screencap -p > "$SHOTS/$1.png" && echo "saved $SHOTS/$1.png"; }
start_app() { "${A[@]}" shell am force-stop com.github.e0ipso.tokkl; "${A[@]}" shell am start -W -n com.github.e0ipso.tokkl/.MainActivity >/dev/null; }
set_scale() { "${A[@]}" shell settings put system font_scale "$1"; }
set_night() { "${A[@]}" shell cmd uimode night "$1" >/dev/null; }
EOF
