# Taps the centre of the first view whose text is exactly $1.
tap_text() {
  local xml b
  xml=$("${A[@]}" exec-out uiautomator dump /dev/tty 2>/dev/null)
  b=$(grep -oE "text=\"$1\"[^>]*bounds=\"\[[0-9]+,[0-9]+\]\[[0-9]+,[0-9]+\]\"" <<<"$xml" | head -1 | grep -oE '[0-9]+' | tail -4 | tr '\n' ' ')
  [ -n "$b" ] || { echo "no view with text $1" >&2; return 1; }
  set -- $b
  "${A[@]}" shell input tap $(( ($1 + $3) / 2 )) $(( ($2 + $4) / 2 ))
}
# Scrolls the content up by $1 px with a slow swipe, so it does not fling.
scroll_up() { "${A[@]}" shell input swipe 540 1900 540 $((1900 - $1)) 1500; }
EOF
