    /**
     * Draws behind transparent system bars, with icons that show on [darkTheme]'s background.
     *
     * Both bars get a light or dark style, never `SystemBarStyle.auto`. `auto` turns on the
     * system's navigation bar contrast enforcement, and from Android 10 on, with three-button
     * navigation, the system then paints its own translucent scrim over the bar: a near-white
     * band on the light background, a lighter one on the dark. A light or dark style turns
     * enforcement off, and its scrims here are transparent, so no Android version draws one.
     */
    private fun drawEdgeToEdge(darkTheme: Boolean) {
        val style = if (darkTheme) {
            SystemBarStyle.dark(Color.TRANSPARENT)
        } else {
            SystemBarStyle.light(Color.TRANSPARENT, Color.TRANSPARENT)
        }
        enableEdgeToEdge(statusBarStyle = style, navigationBarStyle = style)
    }
}"""
new_effect="""            window.setBackgroundDrawable(background.toDrawable())
            showSystemBarIconsFor(darkTheme)
            onDispose {}
        }
    }

    /**
     * Draws behind transparent system bars, with the system's navigation bar contrast enforcement
     * off, so the screen's own background shows under both bars.
     *
     * With enforcement on, which androidx.activity's `enableEdgeToEdge` turns on for
     * `SystemBarStyle.auto`, Android 10 and later paint a translucent scrim over a three-button
     * navigation bar: a near-white band on the light background, a lighter one on the dark.
     * `enableEdgeToEdge` also reapplies its first call's styles on every configuration change,
     * so a later call cannot keep enforcement off. `WindowCompat.enableEdgeToEdge` sets the same
     * window flags once and leaves the icons to [showSystemBarIconsFor].
     */
    private fun drawEdgeToEdge() {
        WindowCompat.enableEdgeToEdge(window)
    }

    /** Dark status and navigation bar icons on a light theme, light icons on a dark one. */
    private fun showSystemBarIconsFor(darkTheme: Boolean) {
        WindowCompat.getInsetsController(window, window.decorView).apply {
            isAppearanceLightStatusBars = !darkTheme
            isAppearanceLightNavigationBars = !darkTheme
        }
    }
}"""
